-- ====================================================================
-- SejarahWira  |  ERA 7: Pemimpin Negara Malaysia (Perdana Menteri)  |  seed_era7.sql
-- 3 naratif (6 + 6 + 6 babak = 18 babak), setiap babak ada 1 quest, serta 50 soalan.
--
-- SETIAP naratif merangkumi enam topik yang sama: (1) peranan jawatan Perdana Menteri, (2) senarai sembilan giliran
-- Perdana Menteri, (3) tugas-tugas Perdana Menteri, (4) pencapaian Tunku, Tun Abdul Razak dan Tun Hussein Onn,
-- (5) pencapaian Tun Dr. Mahathir dan Tun Abdullah, (6) pencapaian Najib, Muhyiddin dan Ismail Sabri.
-- Naratif hanya berbeza pada peranan, suara, watak sampingan dan jenis cabaran.
--
-- Pelajar MERASUK jasad watak rekaan (peranan naratif):
--   Naratif 1 (Siaran Khas dari Pejabat Perdana Menteri) = Wartawan Muda (NPC 121)
--   Naratif 2 (Perdana Menteri Keluar dari Buku Teks)     = Guru Sejarah (NPC 122)
--   Naratif 3 (Album Kad Koleksi Perdana Menteri)         = Murid Penyelidik (NPC 123)
-- Baris dialog tanpa penutur (npcID NULL) ialah baris "Pemain" / "kau" yang dituturkan tokoh peranan.
-- Baris naratif tanpa babak (sceneID NULL): 1 = tugas bersejarah, 2 = pembuka pengajaran,
--   3 = pengenalan peranan oleh Pendekar Bayang.
-- Setiap quest ada "aftermath" (Akibat jika salah), pilihan salah jenis 3/5 ada "consequence",
-- dan satu "Giliran Anda" (turns). Data sahaja (tiada jadual atau lajur baharu).
-- Lencana, artifak dan kemajuan era TIDAK disentuh.
--
-- Jalankan SELEPAS seed.sql (NPC 121-132 dibuat di sini):
--   mysql --default-character-set=utf8mb4 -u root -p <nama_db> < database/seed_era7.sql
-- Selamat dijalankan berulang kali (kandungan Era 7 lama dipadam dahulu). Era lain tidak disentuh.
--
-- NOTA: kandungan Perdana Menteri mengikut bahan asal sahaja; tiada tarikh atau fakta tambahan dimasukkan.
-- ====================================================================
SET NAMES utf8mb4;
START TRANSACTION;

-- 1. Buang kandungan Era 7 lama (babak, dialog, quest, sokongan dipadam sekali: ON DELETE CASCADE).
DELETE FROM Narrative WHERE eraID = 7;

-- 2. NPC baharu Era 7 (nama fail gambar mengikut folder npc sebenar).
ON DUPLICATE KEY UPDATE name = VALUES(name), biography = VALUES(biography), contribution = VALUES(contribution), asset = VALUES(asset);

-- 3. Naratif

-- 4. Babak (sceneStoryline = kad garis masa dalam suara "kau"; asset = latar belakang)

-- 5. Quest (1 Susun Garis Masa, 2 Cari Bukti, 3 Bantu Tokoh, 4 Padanan, 5 Nyahkod Clue)
--    instruction = taklimat misi, description = objektif pembelajaran

-- 6. Sokongan: baris babak = petunjuk babak; baris quest = bisikan (hint), catatan diari (explanation), pujian (feedback)

-- 7. Dialog: baris peranan (tanpa babak) dan dialog babak

-- 8. Bank soalan Era 7 (50 soalan aneka pilihan, ID 701-750)
ON DUPLICATE KEY UPDATE eraID = VALUES(eraID);

DELETE FROM Question WHERE bankID = 7;


COMMIT;