INSERT INTO NPC (npcID, name, biography, contribution, asset) VALUES
(121, 'Wartawan Muda', 'Wartawan muda yang merakam siaran khas tentang Perdana Menteri Malaysia (watak rekaan).', 'Menemu bual tokoh dan melaporkan sejarah kepimpinan negara kepada rakyat.', 'jejaka_melayu.png'),
(122, 'Guru Sejarah', 'Guru Sejarah yang buku teksnya tiba-tiba menghidupkan para Perdana Menteri (watak rekaan).', 'Menjadikan pelajaran tentang pemimpin negara mudah difahami oleh murid.', 'perempuan_melayu.png'),
(123, 'Murid Penyelidik', 'Murid yang membuat album kad koleksi Perdana Menteri untuk projek sekolah (watak rekaan).', 'Mengumpul maklumat tentang pemimpin negara untuk dikongsi bersama rakan.', 'budak_gajet.png'),
(124, 'Tunku Abdul Rahman Putra Al-Haj', 'Perdana Menteri pertama Malaysia.', 'Memperjuangkan kemerdekaan secara rundingan dan merealisasikan Pembentukan Malaysia pada 16 September 1963.', 'tunku_abdul_rahman.png'),
(125, 'Tun Abdul Razak bin Hussein', 'Perdana Menteri kedua Malaysia.', 'Mengembalikan keamanan selepas peristiwa 13 Mei 1969 menerusi MAGERAN dan memperkenalkan Dasar Ekonomi Baru.', 'tun_abdul_razak.png'),
(126, 'Tun Hussein bin Onn', 'Perdana Menteri ketiga Malaysia.', 'Memperkenalkan Amanah Saham Nasional Berhad dan Program Rukun Tetangga.', 'tun_hussein_onn.png'),
(127, 'Tun Dr. Mahathir bin Mohamad', 'Perdana Menteri keempat dan ketujuh Malaysia.', 'Wawasan 2020, pembinaan Putrajaya, KLIA, Menara Berkembar Petronas (KLCC) dan penubuhan HICOM.', 'tun_dr_mahathir.png'),
(128, 'Tun Abdullah bin Ahmad Badawi', 'Perdana Menteri kelima Malaysia.', 'Memperkenalkan Koridor Wilayah Ekonomi dan Pelan Integriti Nasional (PIN).', 'tun_abdullah.png'),
(129, 'Dato'' Sri Mohd Najib bin Tun Abdul Razak', 'Perdana Menteri keenam Malaysia.', 'Memperkenalkan Gagasan 1Malaysia dan Program Transformasi Kerajaan (GTP).', 'dato_sri_mohd_najib.png'),
(130, 'Tan Sri Muhyiddin bin Md Yassin', 'Perdana Menteri kelapan Malaysia.', 'Menubuhkan Majlis Tindakan Ekonomi (MTE) dan mengumumkan bantuan kewangan serta peruntukan besar semasa PKP pandemik COVID-19.', 'tan_sri_muhyiddin.png'),
(131, 'Dato'' Seri Ismail Sabri bin Yaakob', 'Perdana Menteri kesembilan Malaysia.', 'Memperkenalkan konsep Keluarga Malaysia yang meraikan keterangkuman pelbagai agama, bangsa, kaum dan usia.', 'dato_seri_ismail_sabri.png'),
(132, 'Yang di-Pertuan Agong', 'Ketua Utama Negara yang melantik Perdana Menteri secara rasmi.', 'Melantik Perdana Menteri dan menerima nasihatnya, termasuk dalam Mesyuarat Majlis Raja-Raja.', 'raja.png')
INSERT INTO Narrative (narrativeID, narrativeTitle, eraID, summary) VALUES
(701, 'Siaran Khas dari Pejabat Perdana Menteri', 7, 'Masuki peranan wartawan muda yang menemu bual Yang di-Pertuan Agong dan para Perdana Menteri Malaysia. Dalam siaranmu kau mengenali peranan jawatan, senarai sembilan giliran Perdana Menteri, tugas-tugasnya dan pencapaian setiap pemimpin.'),
(702, 'Perdana Menteri Keluar dari Buku Teks', 7, 'Masuki peranan guru Sejarah yang buku teks Unit 7-nya tiba-tiba berpendar dan melepaskan para Perdana Menteri ke dalam bilik darjah. Dalam kelasmu kau mengenali peranan jawatan, senarai sembilan giliran, tugas-tugas dan pencapaian setiap pemimpin.'),
(703, 'Album Kad Koleksi Perdana Menteri', 7, 'Masuki peranan murid penyelidik yang membuat album kad koleksi Perdana Menteri untuk projek sekolah. Dalam setiap halaman kau mengumpul maklumat tentang peranan jawatan, senarai sembilan giliran, tugas-tugas dan pencapaian setiap pemimpin.');
INSERT INTO Scene (sceneID, sceneStoryline, sceneOrder, narrativeID, asset) VALUES
('e7_n1_s1', 'Perkarangan kompleks pentadbiran negara yang megah di bawah langit cerah. Kau, wartawan muda, memegang mikrofon sementara kamera merakam Yang di-Pertuan Agong dan Perdana Menteri pertama yang menunggu temu bual.', 1, 701, 'bangunan_perlembagaan.png'),
('e7_n1_s2', 'Bilik mesyuarat berbendera negeri-negeri dengan peta di atas meja panjang. Kau, wartawan muda, menyusun kad temu bual sementara sembilan giliran Perdana Menteri bersiap untuk sesi gambar kumpulan.', 2, 701, 'bilik_mesyuarat.png'),
('e7_n1_s3', 'Bilik mesyuarat diraja bercorak ukiran emas dengan dokumen terbentang di atas meja panjang. Kau, wartawan muda, berdiri di tepi pintu sambil mencatat empat tugas Perdana Menteri yang diterangkan oleh tetamumu.', 3, 701, 'bilik_mesyuarat_formal.png'),
('e7_n1_s4', 'Sorakan rakyat bergema di Stadium Merdeka. Kau, wartawan muda, menyelit di celah orang ramai dengan kamera di bahu sementara tiga Perdana Menteri yang pertama menanti untuk dirakam.', 4, 701, 'laungan_di_stadium_merdeka.png'),
('e7_n1_s5', 'Pemandangan bandar moden dengan menara pencakar langit, jambatan layang dan kilang di kejauhan. Kau, wartawan muda, merakam dari balkoni sementara Tun Dr. Mahathir dan Tun Abdullah berdiri menunjukkan hasil kepimpinan mereka.', 5, 701, 'pencapaian_ekonomi_perhubungan_dan_perdagangan.png'),
('e7_n1_s6', 'Bilik strategi dengan peta negara dan dokumen bertimbun di atas meja. Kau, wartawan muda, menutup siaran khas sementara tiga Perdana Menteri yang terakhir dalam senarai bersiap menyampaikan pencapaian mereka.', 6, 701, 'bilik_strategi_keselamatan.png'),
('e7_n2_s1', 'Bilik darjah yang diubah suai menjadi bilik mesyuarat dengan peta negara di dinding. Kau, guru Sejarah, membuka buku teks Unit 7 yang tiba-tiba berpendar sementara tetamu ajaib keluar dari halamannya.', 1, 702, 'bilik_mesyuarat_modern.png'),
('e7_n2_s2', 'Bilik mesyuarat bulat dengan peta dunia yang menyala di dinding. Kau, guru Sejarah, memegang sembilan kad kehadiran sementara para Perdana Menteri beratur untuk dipanggil nama satu persatu.', 2, 702, 'bilik_mesyuarat_dunia.png'),
('e7_n2_s3', 'Bilik mesyuarat berukiran emas dengan dokumen terbentang. Kau, guru Sejarah, berdiri di hadapan papan tugas bertanda empat petak sementara empat tetamu dari buku teks menjaga satu petak setiap seorang.', 3, 702, 'bilik_mesyuarat_formal.png'),
('e7_n2_s4', 'Jalan lengang di pekan lama yang muncul dari halaman buku teks. Kau, guru Sejarah, berdiri dengan murid-murid sementara tiga Perdana Menteri yang pertama keluar dari halaman untuk menceritakan pencapaian mereka.', 4, 702, 'peristiwa_13mei1969.png'),
('e7_n2_s5', 'Halaman buku teks bertukar menjadi bandar tiga dimensi dengan menara kembar, jambatan layang dan kilang moden. Kau, guru Sejarah, menunjuk dengan kapur sementara Tun Dr. Mahathir dan Tun Abdullah muncul di tepi bandar itu.', 5, 702, 'pencapaian_ekonomi_perhubungan_dan_perdagangan.png'),
('e7_n2_s6', 'Dewan besar dengan skrin data dan meja pusat kawalan. Kau, guru Sejarah, berdiri di hadapan kelas sementara tiga Perdana Menteri yang terakhir bergilir menyampaikan pencapaian mereka.', 6, 702, 'malaysia_di_pentas_dunia.png'),
('e7_n3_s1', 'Pemandangan Wilayah Persekutuan di waktu senja dengan bangunan bersejarah dan bendera. Kau, murid penyelidik, membuka halaman pertama album yang masih kosong sementara Yang di-Pertuan Agong dan Tunku menunggu.', 1, 703, 'wilayah_persekutuan.png'),
('e7_n3_s2', 'Bilik mesyuarat bulat dengan peta dunia yang menyala. Kau, murid penyelidik, menyusun kad-kad album di atas meja sementara sembilan giliran Perdana Menteri mengelilingi meja itu.', 2, 703, 'bilik_mesyuarat_dunia.png'),
('e7_n3_s3', 'Bilik mesyuarat moden dengan peta negara di dinding. Kau, murid penyelidik, memegang empat kad tugas yang belum lengkap sementara tetamu bergilir membantu mengisi kad itu.', 3, 703, 'bilik_mesyuarat_modern.png'),
('e7_n3_s4', 'Meja peta besar Pembentukan Malaysia dengan lampu kerja yang menyala. Kau, murid penyelidik, membentangkan tiga kad di atas peta sementara Tunku, Tun Abdul Razak dan Tun Hussein Onn berdiri menunggu giliran.', 4, 703, 'perancangan_pembentukan_malaysia.png'),
('e7_n3_s5', 'Perkarangan kompleks pentadbiran negara dengan kolam hiasan yang tenang. Kau, murid penyelidik, memegang dua kad yang paling tebal sementara Tun Dr. Mahathir dan Tun Abdullah menyemak kad itu.', 5, 703, 'bangunan_perlembagaan.png'),
('e7_n3_s6', 'Bilik mesyuarat berukiran emas dengan kerusi tersusun rapi. Kau, murid penyelidik, memegang tiga kad terakhir album sementara tiga Perdana Menteri yang terakhir menunggu album ditutup.', 6, 703, 'bilik_mesyuarat_formal.png');
INSERT INTO Quest (questID, sceneID, questName, instruction, questType, description, questContent) VALUES
(701, 'e7_n1_s1', 'Siaran Langsung: Siapa Perdana Menteri?', 'Pilih pernyataan yang betul tentang peranan jawatan Perdana Menteri untuk siaran akhbar.', '3', 'Mengenal pasti peranan jawatan Perdana Menteri.', '{"prompt": "Seorang pembaca akhbar bertanya kepadamu: yang manakah pernyataan yang betul tentang jawatan Perdana Menteri?", "options": [{"text": "Ketua Kerajaan yang mengetuai pentadbiran negara dan dilantik secara rasmi oleh Yang di-Pertuan Agong.", "isCorrect": true}, {"text": "Ketua Utama Negara yang mengetuai pentadbiran negara dan dilantik secara rasmi oleh Dewan Rakyat.", "isCorrect": false, "consequence": "Berita itu tersiar dengan jawatan yang tersalah. Pembaca menyangka Perdana Menteri ialah Ketua Utama Negara."}, {"text": "Ketua Kerajaan yang diwujudkan sebelum kemerdekaan dan dimansuhkan selepas itu oleh Parlimen.", "isCorrect": false, "consequence": "Berita itu tersiar dengan sejarah yang tersalah. Pembaca menyangka jawatan itu sudah tiada."}], "aftermath": "Berita tentang jawatan Perdana Menteri tersiar tidak tepat. Pembaca akhbar keliru tentang peranan dan sejarahnya.", "turns": [{"after": 7, "options": [{"text": "Yang di-Pertuan Agong.", "isCorrect": true, "reaction": "Tepat, wartawan! Tunku bertepuk tangan dan Tuanku tersenyum ke arah kamera."}, {"text": "Ketua Hakim Negara.", "isCorrect": false, "reaction": "Bukan, wartawan! Tuanku mengangkat kening dan Tunku ketawa sambil menggeleng."}, {"text": "Speaker Dewan Rakyat.", "isCorrect": false, "reaction": "Bukan begitu, wartawan! Tunku menunjuk ke arah Tuanku sambil tersenyum lebar."}], "clue": "Yang melantik juga digelar Ketua Utama Negara, bukan Ketua Kerajaan."}]}'),
(702, 'e7_n1_s2', 'Susun Kad Temu Bual Mengikut Giliran', 'Susun enam Perdana Menteri yang pertama mengikut giliran memegang jawatan.', '1', 'Mengenal pasti senarai Perdana Menteri Malaysia mengikut giliran.', '{"timelineItems": [{"id": 1, "year": "Perdana Menteri pertama", "text": "Tunku Abdul Rahman Putra Al-Haj", "why": "Beliau memegang jawatan pada giliran pertama."}, {"id": 2, "year": "Perdana Menteri kedua", "text": "Tun Abdul Razak bin Hussein", "why": "Beliau memegang jawatan pada giliran kedua."}, {"id": 3, "year": "Perdana Menteri ketiga", "text": "Tun Hussein bin Onn", "why": "Beliau memegang jawatan pada giliran ketiga."}, {"id": 4, "year": "Perdana Menteri keempat", "text": "Tun Dr. Mahathir bin Mohamad", "why": "Beliau kembali pada giliran ketujuh."}, {"id": 5, "year": "Perdana Menteri kelima", "text": "Tun Abdullah bin Ahmad Badawi", "why": "Beliau datang selepas giliran keempat."}, {"id": 6, "year": "Perdana Menteri keenam", "text": "Dato'' Sri Mohd Najib bin Tun Abdul Razak", "why": "Beliau memegang jawatan pada giliran keenam."}], "aftermath": "Kad temu bual tersusun salah. Siaran menyebut nama Perdana Menteri tidak mengikut giliran.", "turns": [{"after": 10, "options": [{"text": "Tun Dr. Mahathir bin Mohamad.", "isCorrect": true, "reaction": "Tepat, wartawan! Tun Dr. Mahathir mengangkat dua jari kerana beliau dua kali memegang jawatan."}, {"text": "Tun Hussein bin Onn.", "isCorrect": false, "reaction": "Itu Perdana Menteri ketiga, wartawan! Tun Hussein ketawa kecil dan mengangkat tiga jari."}, {"text": "Tun Abdullah bin Ahmad Badawi.", "isCorrect": false, "reaction": "Itu Perdana Menteri kelima, wartawan! Tun Abdullah tersenyum dan mengangkat lima jari."}], "clue": "Tokoh ini muncul dua kali dalam senarai, pada giliran keempat dan ketujuh."}]}'),
(703, 'e7_n1_s3', 'Padanan Tajuk Berita: Tugas Perdana Menteri', 'Padankan setiap tugas Perdana Menteri dengan penerangannya.', '4', 'Mengenal pasti tugas-tugas Perdana Menteri.', '{"pairs": [{"text": "Penasihat kepada Yang di-Pertuan Agong", "pair": 1}, {"text": "Mengiringi baginda ke Mesyuarat Majlis Raja-Raja", "pair": 1}, {"text": "Mencadangkan senarai Jemaah Menteri", "pair": 2}, {"text": "Mempengerusikan Mesyuarat Jemaah Menteri", "pair": 2}, {"text": "Ketua Pentadbir Utama", "pair": 3}, {"text": "Merancang dan menyelaraskan semua dasar negara", "pair": 3}, {"text": "Menjalin hubungan diplomatik", "pair": 4}, {"text": "Mencadangkan pelantikan duta, diplomat dan konsulat", "pair": 4}], "aftermath": "Tugas Perdana Menteri tersalah padan. Tajuk berita membawa maklumat yang tidak tepat.", "turns": [{"after": 7, "options": [{"text": "Menjalin hubungan diplomatik.", "isCorrect": true, "reaction": "Tepat, wartawan! Tun Abdul Razak mengangguk dan Tuanku tersenyum."}, {"text": "Mempengerusikan Mesyuarat Jemaah Menteri.", "isCorrect": false, "reaction": "Itu tugas lain, wartawan! Tun Hussein melambai sambil tersenyum."}, {"text": "Merancang dan menyelaraskan semua dasar negara.", "isCorrect": false, "reaction": "Itu tugas Ketua Pentadbir Utama, wartawan! Tun Abdullah menggeleng sambil ketawa."}], "clue": "Duta, diplomat dan konsulat bekerja dengan negara luar."}]}'),
(704, 'e7_n1_s4', 'Misi Stadium: Bukti Perjuangan Kemerdekaan', 'Cari bukti perjuangan kemerdekaan pada gambar Stadium Merdeka.', '2', 'Mengenal pasti pencapaian Tunku Abdul Rahman, Tun Abdul Razak dan Tun Hussein Onn.', '{"bgImage": "../assets/gameAsset/background/laungan_di_stadium_merdeka.png", "hotspots": [{"name": "Tunku di podium: memperjuangkan kemerdekaan secara rundingan", "top": "35%", "left": "52%"}, {"name": "Papan Perisytiharan Kemerdekaan Malaya di podium", "top": "68%", "left": "50%"}, {"name": "Poster Merdeka! Malaya! yang dipegang rakyat", "top": "50%", "left": "12%"}, {"name": "Rakyat bersorak dan mengangkat tangan menyambut kemerdekaan", "top": "62%", "left": "75%"}], "aftermath": "Bukti perjuangan kemerdekaan tersalah cari. Siaran menyiarkan rakaman yang tidak berkaitan.", "turns": [{"after": 8, "options": [{"text": "Pada 16 September 1963.", "isCorrect": true, "reaction": "Tepat, wartawan! Tunku mengangkat tangan dan penonton bersorak."}, {"text": "Pada 13 Mei 1969 itu.", "isCorrect": false, "reaction": "Itu tarikh peristiwa lain, wartawan! Tun Abdul Razak menggeleng perlahan."}, {"text": "Pada 31 Ogos 1957 dahulu.", "isCorrect": false, "reaction": "Itu tarikh lain, wartawan! Tunku tersenyum sambil menggeleng-geleng."}], "clue": "Tarikh itu berlaku pada tahun 1963, bulan September."}]}'),
(705, 'e7_n1_s5', 'Nyahkod Nota Luntur: Koridor dan PIN', 'Baca nota yang luntur dan tentukan pelan yang diperkenalkan bersama Koridor Wilayah Ekonomi.', '5', 'Mengenal pasti pencapaian Tun Dr. Mahathir dan Tun Abdullah.', '{"clueText": "Nota menulis: Tun Abdullah Ahmad Badawi memperkenalkan Koridor Wilayah Ekonomi dan satu pelan lagi. Nama pelan itu sudah luntur dan tidak kelihatan, tetapi ia berkait dengan integriti.", "options": [{"text": "Pelan Integriti Nasional (PIN).", "isCorrect": true}, {"text": "Pelan Industri Nasional (PIN).", "isCorrect": false, "consequence": "Nota itu dibaca dengan pelan yang tidak wujud. Siaran menyebut nama pelan yang tersalah."}, {"text": "Program Transformasi Kerajaan (GTP).", "isCorrect": false, "consequence": "Nota itu dibaca dengan pencapaian Perdana Menteri lain. Siaran bercampur dengan pelan Najib."}], "aftermath": "Nota tentang pencapaian Tun Abdullah disalah baca. Siaran menyebut pelan yang tidak tepat.", "turns": [{"after": 7, "options": [{"text": "Tun Dr. Mahathir Mohamad.", "isCorrect": true, "reaction": "Tepat, wartawan! Tun Dr. Mahathir tersenyum bangga di hadapan menara kembar."}, {"text": "Tun Abdullah Ahmad Badawi.", "isCorrect": false, "reaction": "Bukan, wartawan! Tun Abdullah tersenyum dan menunjuk ke arah Tun Dr. Mahathir."}, {"text": "Dato'' Sri Mohd Najib Tun Abdul Razak.", "isCorrect": false, "reaction": "Bukan, wartawan! Tun Dr. Mahathir menggeleng sambil ketawa kecil."}], "clue": "Beliau Perdana Menteri keempat dan ketujuh, dan beliau jugalah penubuh HICOM."}]}'),
(706, 'e7_n1_s6', 'Penutup Siaran: Tiga Pencapaian Terakhir', 'Pilih pernyataan yang betul tentang pencapaian Perdana Menteri keenam, kelapan dan kesembilan.', '3', 'Mengenal pasti pencapaian Najib, Muhyiddin dan Ismail Sabri.', '{"prompt": "Seorang penonton siaran bertanya: yang manakah pernyataan yang betul tentang pencapaian Perdana Menteri keenam, kelapan dan kesembilan?", "options": [{"text": "Najib: 1Malaysia dan GTP; Muhyiddin: MTE dan bantuan semasa PKP; Ismail Sabri: Keluarga Malaysia.", "isCorrect": true}, {"text": "Najib: Keluarga Malaysia; Muhyiddin: 1Malaysia dan GTP; Ismail Sabri: MTE dan bantuan semasa PKP.", "isCorrect": false, "consequence": "Siaran menyebut pencapaian dengan tokoh yang tersalah. Penonton bercampur-aduk tentang siapa membuat apa."}, {"text": "Najib: MTE dan bantuan semasa PKP; Muhyiddin: Keluarga Malaysia; Ismail Sabri: 1Malaysia dan GTP.", "isCorrect": false, "consequence": "Siaran menyebut pencapaian dengan tokoh yang tersalah. Penonton menyangka tiga pencapaian itu bertukar tempat."}], "aftermath": "Pencapaian tiga Perdana Menteri terakhir tersalah padan. Penonton pulang dengan maklumat yang bercampur.", "turns": [{"after": 8, "options": [{"text": "Pelbagai agama, bangsa, kaum dan usia.", "isCorrect": true, "reaction": "Tepat, wartawan! Dato'' Seri Ismail Sabri tersenyum dan semua bertepuk tangan."}, {"text": "Pelbagai bangsa dan kaum, tanpa agama dan usia.", "isCorrect": false, "reaction": "Ada yang tertinggal, wartawan! Dato'' Seri Ismail Sabri menggeleng sambil menunjuk ke senarai penuh."}, {"text": "Satu kaum dan satu agama sahaja dalam negara.", "isCorrect": false, "reaction": "Bukan, wartawan! Dato'' Seri Ismail Sabri ketawa kerana jawapan itu bertentangan dengan konsepnya."}], "clue": "Konsep itu meraikan keterangkuman, jadi senarainya panjang dan merangkumi usia juga."}]}'),
(707, 'e7_n2_s1', 'Nyahkod Nota Papan Putih', 'Baca nota papan putih yang luntur dan tentukan siapa yang melantik Perdana Menteri secara rasmi.', '5', 'Mengenal pasti peranan jawatan Perdana Menteri.', '{"clueText": "Nota menulis: Perdana Menteri ialah Ketua Kerajaan yang mengetuai pentadbiran negara. Perdana Menteri dilantik secara rasmi oleh satu pihak. Nama pihak itu sudah luntur dan tidak kelihatan, tetapi beliau ialah Ketua Utama Negara.", "options": [{"text": "Yang di-Pertuan Agong.", "isCorrect": true}, {"text": "Speaker Dewan Rakyat.", "isCorrect": false, "consequence": "Nota itu dibaca dengan pihak yang tersalah. Murid-murid mencatat bahawa Speaker melantik Perdana Menteri."}, {"text": "Ketua Hakim Negara.", "isCorrect": false, "consequence": "Nota itu dibaca dengan pihak yang tersalah. Murid-murid keliru tentang siapa Ketua Utama Negara."}], "aftermath": "Nota tentang pelantikan Perdana Menteri disalah baca. Murid-murid mencatat pihak yang tidak tepat.", "turns": [{"after": 7, "options": [{"text": "Ketua Kerajaan.", "isCorrect": true, "reaction": "Tepat, cikgu! Tunku bertepuk tangan dan murid-murid bersorak."}, {"text": "Ketua Utama Negara.", "isCorrect": false, "reaction": "Itu gelaran Yang di-Pertuan Agong, cikgu! Tuanku tersenyum sambil mengangkat tangan."}, {"text": "Ketua Hakim Negara.", "isCorrect": false, "reaction": "Bukan, cikgu! Tunku menggeleng sambil ketawa kecil."}], "clue": "Ketua yang mengetuai pentadbiran negara, bukan Ketua Utama Negara."}]}'),
(708, 'e7_n2_s2', 'Padanan Kad Kehadiran', 'Padankan giliran Perdana Menteri dengan nama tokoh yang memegang jawatan itu.', '4', 'Mengenal pasti senarai Perdana Menteri Malaysia mengikut giliran.', '{"pairs": [{"text": "Perdana Menteri pertama", "pair": 1}, {"text": "Tunku Abdul Rahman Putra Al-Haj", "pair": 1}, {"text": "Perdana Menteri kedua", "pair": 2}, {"text": "Tun Abdul Razak bin Hussein", "pair": 2}, {"text": "Perdana Menteri keempat dan ketujuh", "pair": 3}, {"text": "Tun Dr. Mahathir bin Mohamad", "pair": 3}, {"text": "Perdana Menteri keenam", "pair": 4}, {"text": "Dato'' Sri Mohd Najib bin Tun Abdul Razak", "pair": 4}, {"text": "Perdana Menteri kelapan", "pair": 5}, {"text": "Tan Sri Muhyiddin bin Md Yassin", "pair": 5}, {"text": "Perdana Menteri kesembilan", "pair": 6}, {"text": "Dato'' Seri Ismail Sabri bin Yaakob", "pair": 6}], "aftermath": "Kad kehadiran tersalah padan. Murid-murid mencatat nama Perdana Menteri pada giliran yang salah.", "turns": [{"after": 10, "options": [{"text": "Keempat dan ketujuh.", "isCorrect": true, "reaction": "Tepat, cikgu! Tun Dr. Mahathir mengangkat dua kad kehadiran dengan bangga."}, {"text": "Keempat sahaja.", "isCorrect": false, "reaction": "Aku muncul sekali lagi, cikgu! Tun Dr. Mahathir menunjuk kad kehadiran keduanya."}, {"text": "Ketujuh dan kelapan.", "isCorrect": false, "reaction": "Kelapan itu Tan Sri Muhyiddin, cikgu! Tun Dr. Mahathir ketawa sambil menggeleng."}], "clue": "Beliau dikira dua kali dalam senarai sembilan giliran."}]}'),
(709, 'e7_n2_s3', 'Soalan Murid: Tugas Perdana Menteri', 'Pilih pernyataan yang betul tentang tugas Perdana Menteri untuk murid yang bertanya.', '3', 'Mengenal pasti tugas-tugas Perdana Menteri.', '{"prompt": "Seorang murid mengangkat tangan dan bertanya: yang manakah pernyataan yang betul tentang tugas Perdana Menteri?", "options": [{"text": "Mengiringi Yang di-Pertuan Agong ke Mesyuarat Majlis Raja-Raja dan mempengerusikan Mesyuarat Jemaah Menteri.", "isCorrect": true}, {"text": "Melantik sendiri menteri dan mempengerusikan Mesyuarat Majlis Raja-Raja bersama Yang di-Pertuan Agong.", "isCorrect": false, "consequence": "Murid itu mencatat tugas yang tersalah. Mesyuarat dan pelantikan tertukar tempat dalam bukunya."}, {"text": "Mencadangkan pelantikan Raja-Raja negeri dan merancang dasar untuk satu negeri sahaja.", "isCorrect": false, "consequence": "Murid itu mencatat tugas yang tersalah. Tugas diplomatik dan dasar negara tidak lagi kelihatan dalam catatannya."}], "aftermath": "Tugas Perdana Menteri dicatat tidak tepat. Murid-murid pulang dengan maklumat yang tersalah.", "turns": [{"after": 7, "options": [{"text": "Perdana Menteri.", "isCorrect": true, "reaction": "Tepat, cikgu! Tun Hussein mengangguk dan murid-murid bertepuk tangan."}, {"text": "Yang di-Pertuan Agong.", "isCorrect": false, "reaction": "Tuanku hanya melantik menteri, cikgu! Tun Hussein menggeleng sambil tersenyum."}, {"text": "Ketua Setiausaha Negara.", "isCorrect": false, "reaction": "Bukan, cikgu! Tun Hussein ketawa kerana jawatan itu bukan pengerusinya."}], "clue": "Beliau juga mencadangkan senarai Jemaah Menteri itu."}]}'),
(710, 'e7_n2_s4', 'Susun Urutan Pencapaian Tiga Perdana Menteri', 'Susun peristiwa dan pencapaian mengikut urutan Perdana Menteri yang pertama hingga ketiga.', '1', 'Mengenal pasti pencapaian Tunku Abdul Rahman, Tun Abdul Razak dan Tun Hussein Onn.', '{"timelineItems": [{"id": 1, "year": "Perdana Menteri pertama", "text": "Tunku memperjuangkan kemerdekaan secara rundingan", "why": "Perjuangan ini dilakukan oleh Perdana Menteri pertama."}, {"id": 2, "year": "16 September 1963", "text": "Tunku merealisasikan Pembentukan Malaysia", "why": "Tarikh ini ditandakan dalam sejarah Tunku."}, {"id": 3, "year": "Selepas 13 Mei 1969", "text": "Tun Abdul Razak mengembalikan keamanan melalui MAGERAN dan memperkenalkan DEB", "why": "Peristiwa itu mendahului MAGERAN."}, {"id": 4, "year": "Perdana Menteri ketiga", "text": "Tun Hussein Onn memperkenalkan ASNB dan Program Rukun Tetangga", "why": "Beliau datang selepas Tun Abdul Razak."}], "aftermath": "Urutan pencapaian tersalah susun. Murid-murid menyangka MAGERAN berlaku sebelum kemerdekaan.", "turns": [{"after": 8, "options": [{"text": "Majlis Gerakan Negara.", "isCorrect": true, "reaction": "Tepat, cikgu! Tun Abdul Razak mengangguk dan jalan lengang itu mula bercahaya."}, {"text": "Majlis Gabungan Negara.", "isCorrect": false, "reaction": "Hampir, cikgu! Tun Abdul Razak tersenyum dan menggeleng perlahan."}, {"text": "Majlis Gerakan Nasional.", "isCorrect": false, "reaction": "Hampir, cikgu! Tun Abdul Razak ketawa kecil dan membetulkan sebutan."}], "clue": "Singkatan itu bermula dengan majlis yang menggerakkan negara."}]}'),
(711, 'e7_n2_s5', 'Misi Bandar: Bukti Zaman Wawasan 2020', 'Cari bukti pencapaian Tun Dr. Mahathir pada gambar bandar ini.', '2', 'Mengenal pasti pencapaian Tun Dr. Mahathir dan Tun Abdullah.', '{"bgImage": "../assets/gameAsset/background/pencapaian_ekonomi_perhubungan_dan_perdagangan.png", "hotspots": [{"name": "Menara Berkembar Petronas (KLCC): dibina pada zaman Tun Dr. Mahathir", "top": "20%", "left": "24%"}, {"name": "Kilang moden: HICOM untuk industri berteknologi tinggi", "top": "45%", "left": "78%"}, {"name": "Papan carta menaik: Wawasan 2020 menuju kemajuan", "top": "22%", "left": "90%"}, {"name": "Jambatan layang dan jalan raya: pembangunan seperti KLIA dan Putrajaya", "top": "62%", "left": "38%"}], "aftermath": "Bukti pencapaian Tun Dr. Mahathir tersalah cari. Murid-murid keliru tentang apa yang dibina pada zamannya.", "turns": [{"after": 7, "options": [{"text": "Industri berteknologi tinggi.", "isCorrect": true, "reaction": "Tepat, cikgu! Tun Dr. Mahathir tersenyum dan lampu kilang berkelip."}, {"text": "Industri pertanian tradisional sahaja.", "isCorrect": false, "reaction": "Bukan, cikgu! Tun Dr. Mahathir menggeleng sambil menunjuk ke kilang moden."}, {"text": "Industri kraf tangan di kampung.", "isCorrect": false, "reaction": "Bukan, cikgu! Tun Dr. Mahathir ketawa kerana HICOM bukan untuk kraf kampung."}], "clue": "Kilang dan mesin moden, bukan kerja tangan atau pertanian tradisional."}]}'),
(712, 'e7_n2_s6', 'Nyahkod Kertas Tugasan', 'Baca kertas tugasan yang luntur dan tentukan satu lagi unsur keterangkuman dalam Keluarga Malaysia.', '5', 'Mengenal pasti pencapaian Najib, Muhyiddin dan Ismail Sabri.', '{"clueText": "Kertas tugasan menulis: Dato'' Seri Ismail Sabri memperkenalkan konsep Keluarga Malaysia. Konsep itu meraikan keterangkuman pelbagai agama, bangsa dan kaum. Satu lagi unsur sudah luntur dan tidak kelihatan, tetapi ia berkait dengan umur.", "options": [{"text": "Pelbagai peringkat usia.", "isCorrect": true}, {"text": "Pelbagai jenis pekerjaan.", "isCorrect": false, "consequence": "Kertas itu dibaca dengan unsur yang tiada. Murid-murid menyangka konsep itu berkait dengan pekerjaan."}, {"text": "Pelbagai bahasa negeri.", "isCorrect": false, "consequence": "Kertas itu dibaca dengan unsur yang tiada. Murid-murid menyangka konsep itu berkait dengan bahasa."}], "aftermath": "Kertas tugasan tentang Keluarga Malaysia disalah baca. Murid-murid mencatat unsur yang tidak tepat.", "turns": [{"after": 6, "options": [{"text": "Program Transformasi Kerajaan.", "isCorrect": true, "reaction": "Tepat, cikgu! Dato'' Sri Najib tersenyum dan murid-murid menulis laju."}, {"text": "Pelan Integriti Nasional untuk rakyat.", "isCorrect": false, "reaction": "Itu PIN, cikgu! Dato'' Sri Najib menggeleng sambil tersenyum."}, {"text": "Majlis Tindakan Ekonomi negara.", "isCorrect": false, "reaction": "Itu MTE, cikgu! Dato'' Sri Najib ketawa kecil."}], "clue": "GTP diperkenalkan bersama Gagasan 1Malaysia."}]}'),
(713, 'e7_n3_s1', 'Padanan Kad Pertama: Jawatan Perdana Menteri', 'Padankan setiap kad dengan maklumat tentang jawatan Perdana Menteri.', '4', 'Mengenal pasti peranan jawatan Perdana Menteri.', '{"pairs": [{"text": "Ketua Kerajaan", "pair": 1}, {"text": "Perdana Menteri", "pair": 1}, {"text": "Ketua Utama Negara", "pair": 2}, {"text": "Yang di-Pertuan Agong", "pair": 2}, {"text": "Jawatan Perdana Menteri diwujudkan", "pair": 3}, {"text": "Selepas kemerdekaan", "pair": 3}, {"text": "Jawatan Perdana Menteri kini", "pair": 4}, {"text": "Kekal hingga kini", "pair": 4}], "aftermath": "Kad pertama tersalah padan. Album membawa maklumat yang tidak tepat tentang jawatan Perdana Menteri.", "turns": [{"after": 7, "options": [{"text": "Selepas kemerdekaan negara.", "isCorrect": true, "reaction": "Tepat, murid! Tunku mengangkat ibu jari dan kad pertama bersinar."}, {"text": "Sebelum kemerdekaan negara.", "isCorrect": false, "reaction": "Bukan, murid! Tunku menggeleng sambil ketawa kerana kemerdekaan datang dahulu."}, {"text": "Selepas peristiwa 13 Mei 1969.", "isCorrect": false, "reaction": "Bukan, murid! Tunku menggeleng kerana jawatan itu sudah lama ada sebelumnya."}], "clue": "Tunku ialah Perdana Menteri pertama, dan jawatan itu diwujudkan sebaik sahaja negara merdeka."}]}'),
(714, 'e7_n3_s2', 'Susun Sembilan Kad Perdana Menteri', 'Pilih susunan sembilan giliran Perdana Menteri yang betul untuk album.', '3', 'Mengenal pasti senarai Perdana Menteri Malaysia mengikut giliran.', '{"prompt": "Cikgu projek bertanya: yang manakah susunan sembilan giliran Perdana Menteri yang betul?", "options": [{"text": "Tunku, Razak, Hussein Onn, Mahathir, Abdullah, Najib, Mahathir, Muhyiddin, Ismail Sabri.", "isCorrect": true}, {"text": "Tunku, Razak, Hussein Onn, Mahathir, Najib, Abdullah, Mahathir, Muhyiddin, Ismail Sabri.", "isCorrect": false, "consequence": "Album itu disusun dengan giliran yang tersalah. Najib dan Abdullah bertukar tempat dalam sejarahmu."}, {"text": "Tunku, Razak, Hussein Onn, Mahathir, Abdullah, Najib, Muhyiddin, Mahathir, Ismail Sabri.", "isCorrect": false, "consequence": "Album itu disusun dengan giliran yang tersalah. Muhyiddin dan Mahathir bertukar tempat dalam sejarahmu."}], "aftermath": "Album tersusun dengan giliran yang tidak tepat. Kawan-kawan membaca urutan Perdana Menteri yang tersalah.", "turns": [{"after": 10, "options": [{"text": "Keempat dan ketujuh.", "isCorrect": true, "reaction": "Tepat, murid! Tun Dr. Mahathir menampal dua kad dengan bangga."}, {"text": "Keempat dan kelapan.", "isCorrect": false, "reaction": "Kelapan itu Tan Sri Muhyiddin, murid! Tun Dr. Mahathir menggeleng sambil tersenyum."}, {"text": "Ketujuh sahaja dalam album.", "isCorrect": false, "reaction": "Aku muncul pada giliran keempat juga, murid! Tun Dr. Mahathir mengangkat dua jari."}], "clue": "Beliau dikira dua kali dalam senarai sembilan giliran."}]}'),
(715, 'e7_n3_s3', 'Nyahkod Kad Tugas Keempat', 'Baca kad keempat yang luntur dan tentukan jawatan yang turut dicadangkan oleh Perdana Menteri.', '5', 'Mengenal pasti tugas-tugas Perdana Menteri.', '{"clueText": "Kad keempat menulis: Perdana Menteri menjalin hubungan diplomatik. Beliau mencadangkan pelantikan duta, diplomat dan satu jawatan lagi. Nama jawatan itu sudah luntur dan tidak kelihatan, tetapi ia berkait dengan perwakilan di negara luar.", "options": [{"text": "Konsulat di negara luar.", "isCorrect": true}, {"text": "Setiausaha di pejabat dalam negeri.", "isCorrect": false, "consequence": "Kad itu dibaca dengan jawatan yang tidak wujud. Album mencatat tugas diplomatik yang tersalah."}, {"text": "Jurucakap di Dewan Rakyat.", "isCorrect": false, "consequence": "Kad itu dibaca dengan jawatan yang tidak berkaitan. Album mencatat tugas yang tidak tepat."}], "aftermath": "Kad tugas keempat disalah baca. Album mencatat jawatan diplomatik yang tidak tepat.", "turns": [{"after": 7, "options": [{"text": "Dengan negara luar.", "isCorrect": true, "reaction": "Tepat, murid! Dato'' Seri Ismail Sabri mengangguk dan kad itu bersinar."}, {"text": "Hanya dengan negeri dalam Malaysia.", "isCorrect": false, "reaction": "Bukan, murid! Dato'' Seri Ismail Sabri menggeleng sambil tersenyum."}, {"text": "Hanya dengan Majlis Raja-Raja sahaja.", "isCorrect": false, "reaction": "Bukan, murid! Dato'' Seri Ismail Sabri ketawa kerana itu tugas yang lain."}], "clue": "Duta bertugas di luar negara dan bukan di dalam negeri."}]}'),
(716, 'e7_n3_s4', 'Padanan Kad: Pencapaian Tiga Perdana Menteri', 'Padankan setiap kad dengan pencapaian yang betul.', '4', 'Mengenal pasti pencapaian Tunku Abdul Rahman, Tun Abdul Razak dan Tun Hussein Onn.', '{"pairs": [{"text": "Tunku Abdul Rahman", "pair": 1}, {"text": "Kemerdekaan secara rundingan dan Pembentukan Malaysia", "pair": 1}, {"text": "Tun Abdul Razak", "pair": 2}, {"text": "MAGERAN dan Dasar Ekonomi Baru", "pair": 2}, {"text": "Tun Hussein Onn", "pair": 3}, {"text": "ASNB dan Program Rukun Tetangga", "pair": 3}, {"text": "Dasar Ekonomi Baru", "pair": 4}, {"text": "Membasmi kemiskinan dan menyusun semula masyarakat", "pair": 4}, {"text": "ASNB", "pair": 5}, {"text": "Pemilikan saham bumiputera", "pair": 5}], "aftermath": "Kad pencapaian tersalah padan. Album membawa maklumat yang tidak tepat tentang tiga Perdana Menteri.", "turns": [{"after": 7, "options": [{"text": "Secara rundingan.", "isCorrect": true, "reaction": "Tepat, murid! Tunku mengangguk dan peta di meja seolah-olah bercahaya."}, {"text": "Secara peperangan.", "isCorrect": false, "reaction": "Bukan, murid! Tunku menggeleng kerana beliau memilih berunding."}, {"text": "Secara pemberontakan.", "isCorrect": false, "reaction": "Bukan, murid! Tunku ketawa kecil dan membetulkan jawapanmu."}], "clue": "Tunku memilih cara aman, bukan perang atau pemberontakan."}]}'),
(717, 'e7_n3_s5', 'Soalan Kad: Mahathir dan Abdullah', 'Pilih padanan pencapaian yang betul untuk Tun Dr. Mahathir dan Tun Abdullah.', '3', 'Mengenal pasti pencapaian Tun Dr. Mahathir dan Tun Abdullah.', '{"prompt": "Cikgu projek bertanya: yang manakah padanan pencapaian yang betul untuk Tun Dr. Mahathir dan Tun Abdullah?", "options": [{"text": "Tun Dr. Mahathir: Wawasan 2020, Putrajaya, KLIA, KLCC dan HICOM; Tun Abdullah: Koridor Wilayah Ekonomi dan PIN.", "isCorrect": true}, {"text": "Tun Abdullah: Wawasan 2020, Putrajaya, KLIA, KLCC dan HICOM; Tun Dr. Mahathir: Koridor Wilayah Ekonomi dan PIN.", "isCorrect": false, "consequence": "Kad itu disusun dengan tokoh yang tersalah. Album menyatakan Tun Abdullah membina Putrajaya dan KLIA."}, {"text": "Tun Dr. Mahathir: Wawasan 2020 dan PIN; Tun Abdullah: Putrajaya, KLIA, KLCC, HICOM dan Koridor Wilayah Ekonomi.", "isCorrect": false, "consequence": "Kad itu bercampur-baur pada dua tokoh. Album menyatakan pencapaian yang tidak tepat."}], "aftermath": "Pencapaian dua Perdana Menteri tersalah padan. Album menyatakan tokoh yang tidak tepat.", "turns": [{"after": 6, "options": [{"text": "Pelan Integriti Nasional.", "isCorrect": true, "reaction": "Tepat, murid! Tun Abdullah tersenyum dan kad itu berkilat."}, {"text": "Pelan Industri Nasional.", "isCorrect": false, "reaction": "Hampir, murid! Tun Abdullah ketawa kecil dan membetulkan sebutan."}, {"text": "Program Integriti Negara.", "isCorrect": false, "reaction": "Hampir, murid! Tun Abdullah menggeleng sambil tersenyum."}], "clue": "Singkatan itu menyebut pelan, integriti dan nasional."}]}'),
(718, 'e7_n3_s6', 'Susun Tiga Kad Terakhir Album', 'Susun tiga Perdana Menteri yang terakhir beserta pencapaian mereka mengikut giliran.', '1', 'Mengenal pasti pencapaian Najib, Muhyiddin dan Ismail Sabri.', '{"timelineItems": [{"id": 1, "year": "Perdana Menteri keenam", "text": "Najib memperkenalkan Gagasan 1Malaysia dan Program Transformasi Kerajaan (GTP)", "why": "Beliau memegang jawatan pada giliran keenam."}, {"id": 2, "year": "Perdana Menteri kelapan", "text": "Muhyiddin menubuhkan MTE dan mengumumkan bantuan semasa PKP pandemik COVID-19", "why": "Beliau memegang jawatan pada giliran kelapan."}, {"id": 3, "year": "Perdana Menteri kesembilan", "text": "Ismail Sabri memperkenalkan konsep Keluarga Malaysia", "why": "Beliau penutup dalam senarai sembilan giliran."}], "aftermath": "Tiga kad terakhir tersusun salah. Album menyatakan giliran dan pencapaian yang tidak tepat.", "turns": [{"after": 6, "options": [{"text": "Dato'' Seri Ismail Sabri.", "isCorrect": true, "reaction": "Tepat, murid! Dato'' Seri Ismail Sabri tersenyum dan album pun ditutup dengan tepukan."}, {"text": "Tan Sri Muhyiddin Md Yassin.", "isCorrect": false, "reaction": "Bukan, murid! Tan Sri Muhyiddin tersenyum dan menunjuk ke arah Dato'' Seri Ismail Sabri."}, {"text": "Dato'' Sri Mohd Najib.", "isCorrect": false, "reaction": "Bukan, murid! Dato'' Seri Ismail Sabri ketawa kerana konsep itu miliknya."}], "clue": "Beliau Perdana Menteri kesembilan, penutup dalam senarai."}]}');
INSERT INTO LearningSupport (questID, sceneID, supportType, hint, explanation, feedback) VALUES
(NULL, 'e7_n1_s1', 'hint', 'Perdana Menteri ialah Ketua Kerajaan yang mengetuai pentadbiran negara. Dilantik secara rasmi oleh Yang di-Pertuan Agong, Ketua Utama Negara. Jawatan diwujudkan selepas kemerdekaan dan kekal hingga kini.', NULL, NULL),
(701, NULL, 'hint', 'Ingat tiga perkara: Ketua Kerajaan, dilantik oleh Yang di-Pertuan Agong, diwujudkan selepas kemerdekaan dan kekal hingga kini.', 'Perdana Menteri ialah Ketua Kerajaan yang mengetuai pentadbiran negara, dilantik secara rasmi oleh Yang di-Pertuan Agong (Ketua Utama Negara). Jawatan ini diwujudkan selepas kemerdekaan dan kekal hingga kini.', 'Tepat! Studio bergema dengan tepukan dan kamera mengangguk tanda siaran bersih.'),
(NULL, 'e7_n1_s2', 'hint', 'Sembilan giliran: Tunku Abdul Rahman, Tun Abdul Razak, Tun Hussein Onn, Tun Dr. Mahathir, Tun Abdullah, Najib, Tun Dr. Mahathir semula, Muhyiddin dan Ismail Sabri.', NULL, NULL),
(702, NULL, 'hint', 'Mulakan dengan Tunku, kemudian Tun Abdul Razak, Tun Hussein Onn, Tun Dr. Mahathir, Tun Abdullah dan Najib.', 'Senarai Perdana Menteri: (1) Tunku Abdul Rahman Putra Al-Haj, (2) Tun Abdul Razak, (3) Tun Hussein Onn, (4) Tun Dr. Mahathir, (5) Tun Abdullah Ahmad Badawi, (6) Dato Sri Mohd Najib, (7) Tun Dr. Mahathir, (8) Tan Sri Muhyiddin Md Yassin, (9) Dato Seri Ismail Sabri Yaakob.', 'Betul! Enam kad tersusun kemas dan semua Perdana Menteri mengangguk puas.'),
(NULL, 'e7_n1_s3', 'hint', 'Empat tugas: penasihat kepada Yang di-Pertuan Agong, mencadangkan senarai Jemaah Menteri, Ketua Pentadbir Utama dan menjalin hubungan diplomatik.', NULL, NULL),
(703, NULL, 'hint', 'Empat tugas: penasihat, Jemaah Menteri, Ketua Pentadbir Utama dan hubungan diplomatik. Padankan satu persatu.', 'Tugas Perdana Menteri: penasihat kepada Yang di-Pertuan Agong (mengiringi baginda ke Mesyuarat Majlis Raja-Raja); mencadangkan senarai Jemaah Menteri dan mempengerusikan mesyuaratnya; Ketua Pentadbir Utama (merancang dan menyelaraskan semua dasar negara, memastikan pembangunan ditingkatkan demi kesejahteraan rakyat); menjalin hubungan diplomatik (mencadangkan pelantikan duta, diplomat dan konsulat).', 'Betul! Empat tajuk berita bertemu pasangannya dan suntingan siaran pun siap.'),
(NULL, 'e7_n1_s4', 'hint', 'Tunku: kemerdekaan secara rundingan dan Pembentukan Malaysia pada 16 September 1963. Tun Abdul Razak: MAGERAN dan DEB. Tun Hussein Onn: ASNB dan Rukun Tetangga.', NULL, NULL),
(704, NULL, 'hint', 'Cari Tunku di podium, papan perisytiharan, poster Merdeka dan rakyat yang bersorak.', 'Tunku Abdul Rahman: kemerdekaan secara rundingan dan Pembentukan Malaysia (16 September 1963). Tun Abdul Razak: MAGERAN selepas 13 Mei 1969 dan Dasar Ekonomi Baru (DEB) untuk membasmi kemiskinan dan menyusun semula masyarakat. Tun Hussein Onn: ASNB untuk pemilikan saham bumiputera dan Program Rukun Tetangga untuk perpaduan.', 'Hebat! Empat bukti ditemui dan rakaman stadium siap untuk disiarkan.'),
(NULL, 'e7_n1_s5', 'hint', 'Tun Dr. Mahathir: Wawasan 2020, Putrajaya, KLIA, KLCC, HICOM. Tun Abdullah: Koridor Wilayah Ekonomi dan Pelan Integriti Nasional (PIN).', NULL, NULL),
(705, NULL, 'hint', 'Pelan itu berkait dengan integriti. Ingat singkatan PIN.', 'Tun Dr. Mahathir: Wawasan 2020, pembinaan Putrajaya, KLIA, Menara Berkembar Petronas (KLCC) dan penubuhan HICOM untuk industri berteknologi tinggi. Tun Abdullah Ahmad Badawi: Koridor Wilayah Ekonomi dan Pelan Integriti Nasional (PIN).', 'Betul! Nota yang luntur jelas semula dan siaran diteruskan dengan lancar.'),
(NULL, 'e7_n1_s6', 'hint', 'Najib: Gagasan 1Malaysia dan GTP. Muhyiddin: MTE dan bantuan semasa PKP. Ismail Sabri: Keluarga Malaysia.', NULL, NULL),
(706, NULL, 'hint', 'Ingat: Najib 1Malaysia dan GTP, Muhyiddin MTE dan PKP, Ismail Sabri Keluarga Malaysia.', 'Dato'' Sri Mohd Najib: Gagasan 1Malaysia dan Program Transformasi Kerajaan (GTP). Tan Sri Muhyiddin: Majlis Tindakan Ekonomi (MTE) dan bantuan kewangan serta peruntukan besar semasa PKP pandemik COVID-19. Dato'' Seri Ismail Sabri: konsep Keluarga Malaysia yang meraikan keterangkuman pelbagai agama, bangsa, kaum dan usia.', 'Betul! Siaran khas ditutup dengan tepukan gemuruh dan lampu studio padam perlahan.'),
(NULL, 'e7_n2_s1', 'hint', 'Perdana Menteri ialah Ketua Kerajaan, dilantik secara rasmi oleh Yang di-Pertuan Agong (Ketua Utama Negara). Jawatan diwujudkan selepas kemerdekaan dan kekal hingga kini.', NULL, NULL),
(707, NULL, 'hint', 'Pihak itu ialah Ketua Utama Negara, yang melantik Perdana Menteri secara rasmi.', 'Perdana Menteri ialah Ketua Kerajaan yang mengetuai pentadbiran negara, dilantik secara rasmi oleh Yang di-Pertuan Agong (Ketua Utama Negara). Jawatan ini diwujudkan selepas kemerdekaan dan kekal hingga kini.', 'Betul! Nota di papan putih jelas semula dan murid-murid bertepuk tangan.'),
(NULL, 'e7_n2_s2', 'hint', 'Sembilan giliran: Tunku, Tun Abdul Razak, Tun Hussein Onn, Tun Dr. Mahathir (keempat), Tun Abdullah, Najib, Tun Dr. Mahathir (ketujuh), Muhyiddin dan Ismail Sabri.', NULL, NULL),
(708, NULL, 'hint', 'Satu tokoh sahaja yang dipasangkan dengan dua giliran, iaitu keempat dan ketujuh.', 'Senarai Perdana Menteri: Tunku Abdul Rahman Putra Al-Haj (pertama), Tun Abdul Razak (kedua), Tun Hussein Onn (ketiga), Tun Dr. Mahathir (keempat dan ketujuh), Tun Abdullah Ahmad Badawi (kelima), Dato'' Sri Mohd Najib (keenam), Tan Sri Muhyiddin Md Yassin (kelapan), Dato'' Seri Ismail Sabri Yaakob (kesembilan).', 'Betul! Enam kad kehadiran bertemu pasangannya dan kelas bersorak.'),
(NULL, 'e7_n2_s3', 'hint', 'Empat tugas: penasihat kepada Yang di-Pertuan Agong, mencadangkan senarai Jemaah Menteri, Ketua Pentadbir Utama dan menjalin hubungan diplomatik.', NULL, NULL),
(709, NULL, 'hint', 'Perdana Menteri mengiringi Yang di-Pertuan Agong dan mempengerusikan Jemaah Menteri, bukan melantik atau mempengerusikan Majlis Raja-Raja.', 'Tugas Perdana Menteri: penasihat kepada Yang di-Pertuan Agong (mengiringi baginda ke Mesyuarat Majlis Raja-Raja); mencadangkan senarai Jemaah Menteri dan mempengerusikan mesyuaratnya; Ketua Pentadbir Utama (merancang dan menyelaraskan semua dasar negara, memastikan pembangunan ditingkatkan demi kesejahteraan rakyat); menjalin hubungan diplomatik (mencadangkan pelantikan duta, diplomat dan konsulat).', 'Betul! Papan tugas berkilau dan tepukan murid menggegar bilik darjah.'),
(NULL, 'e7_n2_s4', 'hint', 'Tunku: kemerdekaan secara rundingan dan Pembentukan Malaysia. Tun Abdul Razak: MAGERAN dan DEB. Tun Hussein Onn: ASNB dan Rukun Tetangga.', NULL, NULL),
(710, NULL, 'hint', 'Mulakan dengan Tunku dan kemerdekaan, kemudian Pembentukan Malaysia, 13 Mei 1969, dan akhirnya Tun Hussein Onn.', 'Tunku: kemerdekaan secara rundingan dan Pembentukan Malaysia pada 16 September 1963. Tun Abdul Razak: MAGERAN selepas peristiwa 13 Mei 1969 dan Dasar Ekonomi Baru (DEB). Tun Hussein Onn: ASNB (pemilikan saham bumiputera) dan Program Rukun Tetangga (perpaduan).', 'Betul! Empat peristiwa tersusun dan jalan lengang bertukar menjadi lorong yang terang.'),
(NULL, 'e7_n2_s5', 'hint', 'Tun Dr. Mahathir: Wawasan 2020, Putrajaya, KLIA, KLCC, HICOM. Tun Abdullah: Koridor Wilayah Ekonomi dan Pelan Integriti Nasional (PIN).', NULL, NULL),
(711, NULL, 'hint', 'Cari menara kembar, kilang moden, papan carta dan jambatan layang.', 'Tun Dr. Mahathir: Wawasan 2020, pembinaan Putrajaya, KLIA, Menara Berkembar Petronas (KLCC) dan penubuhan HICOM untuk industri berteknologi tinggi. Tun Abdullah Ahmad Badawi: Koridor Wilayah Ekonomi dan Pelan Integriti Nasional (PIN).', 'Hebat! Empat bukti ditemui dan bandar tiga dimensi bersinar terang.'),
(NULL, 'e7_n2_s6', 'hint', 'Najib: Gagasan 1Malaysia dan GTP. Muhyiddin: MTE dan bantuan semasa PKP. Ismail Sabri: Keluarga Malaysia.', NULL, NULL),
(712, NULL, 'hint', 'Unsur itu berkait dengan umur. Ingat agama, bangsa, kaum dan usia.', 'Dato'' Sri Mohd Najib: Gagasan 1Malaysia dan Program Transformasi Kerajaan (GTP). Tan Sri Muhyiddin: Majlis Tindakan Ekonomi (MTE) dan bantuan kewangan serta peruntukan besar semasa PKP pandemik COVID-19. Dato'' Seri Ismail Sabri: konsep Keluarga Malaysia yang meraikan keterangkuman pelbagai agama, bangsa, kaum dan usia.', 'Betul! Kertas tugasan jelas semula dan dewan bergema dengan tepukan.'),
(NULL, 'e7_n3_s1', 'hint', 'Perdana Menteri ialah Ketua Kerajaan, dilantik oleh Yang di-Pertuan Agong (Ketua Utama Negara). Jawatan diwujudkan selepas kemerdekaan dan kekal hingga kini.', NULL, NULL),
(713, NULL, 'hint', 'Padankan Ketua Kerajaan dengan Perdana Menteri dan Ketua Utama Negara dengan Yang di-Pertuan Agong.', 'Perdana Menteri ialah Ketua Kerajaan yang mengetuai pentadbiran negara, dilantik secara rasmi oleh Yang di-Pertuan Agong (Ketua Utama Negara). Jawatan ini diwujudkan selepas kemerdekaan dan kekal hingga kini.', 'Betul! Empat kad bertemu pasangannya dan halaman pertama album berseri-seri.'),
(NULL, 'e7_n3_s2', 'hint', 'Sembilan giliran: Tunku, Tun Abdul Razak, Tun Hussein Onn, Tun Dr. Mahathir (keempat), Tun Abdullah, Najib, Tun Dr. Mahathir (ketujuh), Muhyiddin dan Ismail Sabri.', NULL, NULL),
(714, NULL, 'hint', 'Susunan: Tunku, Razak, Hussein Onn, Mahathir, Abdullah, Najib, Mahathir semula, Muhyiddin, Ismail Sabri.', 'Senarai Perdana Menteri: Tunku Abdul Rahman Putra Al-Haj, Tun Abdul Razak, Tun Hussein Onn, Tun Dr. Mahathir (keempat), Tun Abdullah Ahmad Badawi, Dato'' Sri Mohd Najib, Tun Dr. Mahathir (ketujuh), Tan Sri Muhyiddin Md Yassin dan Dato'' Seri Ismail Sabri Yaakob.', 'Betul! Sembilan kad tersusun kemas dan album pun berat dengan sejarah.'),
(NULL, 'e7_n3_s3', 'hint', 'Empat tugas: penasihat kepada Yang di-Pertuan Agong, mencadangkan senarai Jemaah Menteri, Ketua Pentadbir Utama dan menjalin hubungan diplomatik.', NULL, NULL),
(715, NULL, 'hint', 'Jawatan itu berkait dengan perwakilan di negara luar, selain duta dan diplomat.', 'Tugas Perdana Menteri: penasihat kepada Yang di-Pertuan Agong (mengiringi baginda ke Mesyuarat Majlis Raja-Raja); mencadangkan senarai Jemaah Menteri dan mempengerusikan mesyuaratnya; Ketua Pentadbir Utama (merancang dan menyelaraskan semua dasar negara, memastikan pembangunan ditingkatkan demi kesejahteraan rakyat); menjalin hubungan diplomatik (mencadangkan pelantikan duta, diplomat dan konsulat).', 'Betul! Kad keempat jelas semula dan semua empat kad tugas siap diisi.'),
(NULL, 'e7_n3_s4', 'hint', 'Tunku: kemerdekaan secara rundingan dan Pembentukan Malaysia. Tun Abdul Razak: MAGERAN dan DEB. Tun Hussein Onn: ASNB dan Rukun Tetangga.', NULL, NULL),
(716, NULL, 'hint', 'Tunku ialah kemerdekaan, Tun Abdul Razak ialah MAGERAN dan DEB, Tun Hussein Onn ialah ASNB dan Rukun Tetangga.', 'Tunku: kemerdekaan secara rundingan dan Pembentukan Malaysia (16 September 1963). Tun Abdul Razak: MAGERAN selepas 13 Mei 1969 dan Dasar Ekonomi Baru (DEB) untuk membasmi kemiskinan dan menyusun semula masyarakat. Tun Hussein Onn: ASNB untuk pemilikan saham bumiputera dan Program Rukun Tetangga untuk perpaduan.', 'Betul! Lima kad bertemu pasangannya dan halaman album berseri-seri.'),
(NULL, 'e7_n3_s5', 'hint', 'Tun Dr. Mahathir: Wawasan 2020, Putrajaya, KLIA, KLCC, HICOM. Tun Abdullah: Koridor Wilayah Ekonomi dan Pelan Integriti Nasional (PIN).', NULL, NULL),
(717, NULL, 'hint', 'Tun Dr. Mahathir ialah Wawasan 2020 dan pembinaan besar. Tun Abdullah ialah Koridor Wilayah Ekonomi dan PIN.', 'Tun Dr. Mahathir: Wawasan 2020, pembinaan Putrajaya, KLIA, Menara Berkembar Petronas (KLCC) dan penubuhan HICOM untuk industri berteknologi tinggi. Tun Abdullah Ahmad Badawi: Koridor Wilayah Ekonomi dan Pelan Integriti Nasional (PIN).', 'Betul! Dua kad tebal tersusun kemas dan album semakin cantik.'),
(NULL, 'e7_n3_s6', 'hint', 'Najib: Gagasan 1Malaysia dan GTP. Muhyiddin: MTE dan bantuan semasa PKP. Ismail Sabri: Keluarga Malaysia.', NULL, NULL),
(718, NULL, 'hint', 'Giliran keenam Najib, kelapan Muhyiddin dan kesembilan Ismail Sabri.', 'Dato'' Sri Mohd Najib: Gagasan 1Malaysia dan Program Transformasi Kerajaan (GTP). Tan Sri Muhyiddin: Majlis Tindakan Ekonomi (MTE) dan bantuan kewangan serta peruntukan besar semasa PKP pandemik COVID-19. Dato'' Seri Ismail Sabri: konsep Keluarga Malaysia yang meraikan keterangkuman pelbagai agama, bangsa, kaum dan usia.', 'Betul! Tiga kad terakhir tersusun dan album ditutup dengan tepukan.');
INSERT INTO DialogueLine (npcID, narrativeID, sceneID, dialogueLine, sequenceOrder) VALUES
(121, 701, NULL, 'Tugasku ialah memastikan rakyat mengenali pemimpin negara mereka. Jika wartawan berhenti bertanya, sejarah pun senyap, {nama}. Terima kasih kerana meminjamkan suaramu!', 1),
(121, 701, NULL, 'Setiap Perdana Menteri membawa tugas dan pencapaian sendiri. Apabila kita mengenali mereka, kita menghargai perjalanan negara dari kemerdekaan hingga kini.', 2),
(121, 701, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, wartawan muda dengan kad akhbar di leher dan mikrofon di tangan. Kamera sudah menyala, siaran khas bermula! Lihat dengan matanya dan bercakaplah dengan suaranya.', 3),
(132, 701, 'e7_n1_s1', 'Wartawan muda, selamat datang! Beta Yang di-Pertuan Agong, Ketua Utama Negara. Hari ini kau bertanya tentang jawatan Perdana Menteri, bukan?', 1),
(NULL, 701, 'e7_n1_s1', 'Betul, Tuanku! Kamera sudah merakam. Siapakah yang mengetuai pentadbiran negara kita, Tuanku?', 2),
(124, 701, 'e7_n1_s1', 'Itu kerja Perdana Menteri, wartawan! Beliau ialah Ketua Kerajaan yang mengetuai pentadbiran negara. Akulah orang pertama memegang jawatan itu, tahu?', 3),
(132, 701, 'e7_n1_s1', 'Dan Perdana Menteri dilantik secara rasmi oleh Beta. Itulah pembahagian tugasnya: Beta Ketua Utama Negara, Perdana Menteri Ketua Kerajaan.', 4),
(124, 701, 'e7_n1_s1', 'Jawatan ini diwujudkan selepas kemerdekaan, dan ia kekal hingga hari ini. Dari aku sampai ke Perdana Menteri seterusnya, wartawan!', 5),
(NULL, 701, 'e7_n1_s1', 'Catatan penuh! Ketua Kerajaan, dilantik oleh Yang di-Pertuan Agong, diwujudkan selepas kemerdekaan dan kekal hingga kini. Betul, Tunku?', 6),
(124, 701, 'e7_n1_s1', 'Betul, wartawan! Tapi Tunku nak uji sedikit sebelum siaran bersambung. Siapakah yang melantik Perdana Menteri secara rasmi?', 7),
(NULL, 701, 'e7_n1_s2', 'Hadirin sekalian, ini sesi gambar barisan Perdana Menteri Malaysia! Satu persatu, sila kenalkan diri mengikut giliran. Mikrofon dihidupkan!', 1),
(124, 701, 'e7_n1_s2', 'Aku Tunku Abdul Rahman Putra Al-Haj, Perdana Menteri pertama. Giliran pertama, jadi aku bercakap dahulu, wartawan!', 2),
(125, 701, 'e7_n1_s2', 'Tun Abdul Razak bin Hussein, Perdana Menteri kedua. Aku berdiri tepat selepas Tunku.', 3),
(126, 701, 'e7_n1_s2', 'Tun Hussein bin Onn, Perdana Menteri ketiga. Tiga ialah nombor yang cantik, bukan?', 4),
(127, 701, 'e7_n1_s2', 'Tun Dr. Mahathir bin Mohamad. Aku Perdana Menteri keempat, dan sekali lagi Perdana Menteri ketujuh! Dua giliran, seorang aku!', 5),
(128, 701, 'e7_n1_s2', 'Tun Abdullah bin Ahmad Badawi, Perdana Menteri kelima. Hadir, wartawan!', 6),
(129, 701, 'e7_n1_s2', 'Dato'' Sri Mohd Najib bin Tun Abdul Razak, Perdana Menteri keenam. Senyum untuk kamera!', 7),
(130, 701, 'e7_n1_s2', 'Tan Sri Muhyiddin bin Md Yassin, Perdana Menteri kelapan, selepas Tun Dr. Mahathir kali kedua.', 8),
(131, 701, 'e7_n1_s2', 'Dato'' Seri Ismail Sabri bin Yaakob, Perdana Menteri kesembilan! Akulah penutup barisan.', 9),
(124, 701, 'e7_n1_s2', 'Wartawan, kad temu bualmu bercampur-aduk! Sebelum menyusunnya, jawab soalan Tunku: siapakah Perdana Menteri keempat?', 10),
(132, 701, 'e7_n1_s3', 'Wartawan, bilik ini ialah tempat Mesyuarat Majlis Raja-Raja. Perdana Menteri mengiringi Beta ke sini, kerana beliau Penasihat kepada Yang di-Pertuan Agong.', 1),
(125, 701, 'e7_n1_s3', 'Itu tugas pertama, wartawan. Aku mengiringi Yang di-Pertuan Agong ke Mesyuarat Majlis Raja-Raja sebagai penasihat. Berdiri tegak, senyum sedikit!', 2),
(126, 701, 'e7_n1_s3', 'Tugas kedua: mencadangkan senarai Jemaah Menteri. Aku juga mempengerusikan Mesyuarat Jemaah Menteri bagi menteri yang dilantik oleh Yang di-Pertuan Agong.', 3),
(128, 701, 'e7_n1_s3', 'Tugas ketiga: Ketua Pentadbir Utama! Aku merancang dan menyelaraskan semua dasar negara, dan memastikan pembangunan ditingkatkan demi kesejahteraan rakyat.', 4),
(132, 701, 'e7_n1_s3', 'Tugas keempat: menjalin hubungan diplomatik. Perdana Menteri mencadangkan pelantikan duta, diplomat dan konsulat untuk menjalin kerjasama dengan negara luar.', 5),
(NULL, 701, 'e7_n1_s3', 'Empat tugas, empat tajuk berita! Penasihat, Jemaah Menteri, Ketua Pentadbir Utama dan Hubungan Diplomatik. Nanti saya padankan!', 6),
(125, 701, 'e7_n1_s3', 'Sebelum itu, soalan pantas. Tugas mencadangkan pelantikan duta, diplomat dan konsulat termasuk dalam tugas yang mana?', 7),
(124, 701, 'e7_n1_s4', 'Wartawan! Ini Stadium Merdeka. Aku memperjuangkan kemerdekaan secara rundingan, bukan secara perang. Bijak, bukan?', 1),
(NULL, 701, 'e7_n1_s4', 'Bijak sekali, Tunku! Dan apakah lagi yang Tunku capai?', 2),
(124, 701, 'e7_n1_s4', 'Pada 16 September 1963, aku merealisasikan Pembentukan Malaysia. Itulah dua pencapaian besarku!', 3),
(125, 701, 'e7_n1_s4', 'Aku Tun Abdul Razak. Selepas peristiwa 13 Mei 1969, aku mengembalikan keamanan menerusi Majlis Gerakan Negara, atau MAGERAN.', 4),
(125, 701, 'e7_n1_s4', 'Aku juga memperkenalkan Dasar Ekonomi Baru (DEB) untuk membasmi kemiskinan dan menyusun semula masyarakat.', 5),
(126, 701, 'e7_n1_s4', 'Giliran aku, Tun Hussein Onn! Aku memperkenalkan Amanah Saham Nasional Berhad (ASNB) untuk pemilikan saham bumiputera.', 6),
(126, 701, 'e7_n1_s4', 'Aku juga memperkenalkan Program Rukun Tetangga untuk perpaduan. Jiran bertegur sapa, negara pun aman!', 7),
(124, 701, 'e7_n1_s4', 'Wartawan, cari bukti pada gambar stadium ini. Tapi dahulu soalan Tunku: pada tarikh manakah Pembentukan Malaysia direalisasikan?', 8),
(127, 701, 'e7_n1_s5', 'Wartawan, tengok pemandangan ini! Aku Tun Dr. Mahathir. Aku memperkenalkan Wawasan 2020, wawasan untuk membawa negara ke hadapan!', 1),
(127, 701, 'e7_n1_s5', 'Pembinaan Putrajaya, KLIA dan Menara Berkembar Petronas (KLCC) berlaku pada zamanku. Menara kembar itu kebanggaan kita!', 2),
(127, 701, 'e7_n1_s5', 'Aku juga menubuhkan HICOM untuk industri berteknologi tinggi. Kilang dan mesin moden, itulah matlamatnya!', 3),
(128, 701, 'e7_n1_s5', 'Aku Tun Abdullah Ahmad Badawi, wartawan. Aku memperkenalkan Koridor Wilayah Ekonomi dan Pelan Integriti Nasional, atau PIN.', 4),
(128, 701, 'e7_n1_s5', 'PIN ialah Pelan Integriti Nasional. Ingat singkatan itu, ya! Sebut sekali lagi: P-I-N.', 5),
(NULL, 701, 'e7_n1_s5', 'Dua Perdana Menteri, banyak pencapaian! Wawasan 2020, Putrajaya, KLIA, KLCC, HICOM, Koridor Wilayah Ekonomi dan PIN. Saya catat semua!', 6),
(127, 701, 'e7_n1_s5', 'Wartawan, nota di tanganmu itu luntur. Tapi dahulu, jawab soalanku: Wawasan 2020 diperkenalkan oleh siapa?', 7),
(129, 701, 'e7_n1_s6', 'Wartawan, aku Dato'' Sri Mohd Najib bin Tun Abdul Razak. Aku memperkenalkan Gagasan 1Malaysia dan Program Transformasi Kerajaan, atau GTP.', 1),
(129, 701, 'e7_n1_s6', 'Satu ialah gagasan, satu lagi ialah program. Jangan tertukar, ya! Nanti siaran songsang.', 2),
(130, 701, 'e7_n1_s6', 'Aku Tan Sri Muhyiddin bin Md Yassin. Aku menubuhkan Majlis Tindakan Ekonomi (MTE) dan mengumumkan bantuan kewangan serta peruntukan besar semasa Perintah Kawalan Pergerakan (PKP).', 3),
(130, 701, 'e7_n1_s6', 'Itu semasa pandemik COVID-19, wartawan. Rakyat duduk di rumah dan bantuan pun diumumkan.', 4),
(131, 701, 'e7_n1_s6', 'Aku Dato'' Seri Ismail Sabri bin Yaakob. Aku memperkenalkan konsep Keluarga Malaysia.', 5),
(131, 701, 'e7_n1_s6', 'Keluarga Malaysia meraikan keterangkuman pelbagai agama, bangsa, kaum dan usia. Semua ada tempat di meja makan!', 6),
(NULL, 701, 'e7_n1_s6', 'Najib: 1Malaysia dan GTP. Muhyiddin: MTE dan bantuan semasa PKP. Ismail Sabri: Keluarga Malaysia. Siaran khas ditutup dengan kemas!', 7),
(131, 701, 'e7_n1_s6', 'Soalan penutup untukmu, wartawan: Keluarga Malaysia meraikan keterangkuman apa?', 8),
(122, 702, NULL, 'Tugasku ialah memastikan murid-murid mengenali pemimpin yang membina negara mereka. Jika guru berhenti bercerita, buku teks hanya jadi kertas, {nama}. Terima kasih kerana meminjamkan suaramu!', 1),
(122, 702, NULL, 'Para Perdana Menteri bukan sekadar nama dalam buku. Mereka mempunyai tugas, giliran dan pencapaian yang boleh kita pelajari untuk menghargai perjalanan negara.', 2),
(122, 702, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, guru yang paling disayangi murid-muridnya. Kapur sudah di tangan dan buku teks Unit 7 mula berpendar. Lihat dengan matanya dan bercakaplah dengan suaranya.', 3),
(NULL, 702, 'e7_n2_s1', 'Murid-murid, buka buku teks Unit 7! Eh, kenapa halaman ini berpendar? Ada orang keluar dari buku!', 1),
(124, 702, 'e7_n2_s1', 'Cikgu! Aku Tunku Abdul Rahman, tersangkut dalam bab Peranan Jawatan Perdana Menteri. Tolong tarik aku keluar!', 2),
(132, 702, 'e7_n2_s1', 'Beta Yang di-Pertuan Agong, Ketua Utama Negara. Cikgu, Beta yang melantik Perdana Menteri secara rasmi.', 3),
(124, 702, 'e7_n2_s1', 'Dan aku, sebagai Perdana Menteri, ialah Ketua Kerajaan yang mengetuai pentadbiran negara. Dua ketua, dua tugas berbeza, cikgu!', 4),
(132, 702, 'e7_n2_s1', 'Jawatan Perdana Menteri diwujudkan selepas kemerdekaan, dan kekal hingga kini. Murid-murid tak perlu cari tarikh pemansuhan, kerana tiada!', 5),
(NULL, 702, 'e7_n2_s1', 'Faham! Ketua Kerajaan, dilantik oleh Yang di-Pertuan Agong. Tapi nota di papan putih ini sudah luntur!', 6),
(124, 702, 'e7_n2_s1', 'Cikgu, sebelum cikgu baca nota itu, jawab soalan Tunku: Perdana Menteri ialah ketua apa?', 7),
(NULL, 702, 'e7_n2_s2', 'Baik, panggilan nama! Satu persatu, sebut giliran masing-masing. Cikgu ada kad kehadiran sembilan keping!', 1),
(124, 702, 'e7_n2_s2', 'Hadir! Tunku Abdul Rahman Putra Al-Haj, Perdana Menteri pertama.', 2),
(125, 702, 'e7_n2_s2', 'Hadir, cikgu! Tun Abdul Razak bin Hussein, Perdana Menteri kedua.', 3),
(126, 702, 'e7_n2_s2', 'Hadir! Tun Hussein bin Onn, Perdana Menteri ketiga.', 4),
(127, 702, 'e7_n2_s2', 'Hadir dua kali, cikgu! Tun Dr. Mahathir bin Mohamad, Perdana Menteri keempat dan juga ketujuh. Kad kehadiran aku dua keping!', 5),
(128, 702, 'e7_n2_s2', 'Tun Abdullah bin Ahmad Badawi, Perdana Menteri kelima. Hadir!', 6),
(129, 702, 'e7_n2_s2', 'Dato'' Sri Mohd Najib bin Tun Abdul Razak, keenam. Hadir, cikgu!', 7),
(130, 702, 'e7_n2_s2', 'Tan Sri Muhyiddin bin Md Yassin, kelapan. Hadir!', 8),
(131, 702, 'e7_n2_s2', 'Dato'' Seri Ismail Sabri bin Yaakob, kesembilan. Hadir, penutup senarai!', 9),
(127, 702, 'e7_n2_s2', 'Cikgu, kad kehadiran aku dua keping tadi. Sebelum cikgu padankan, jawab: aku Perdana Menteri yang keberapa?', 10),
(NULL, 702, 'e7_n2_s3', 'Murid-murid, hari ini papan tugas Perdana Menteri ada empat petak. Setiap petak dijaga oleh seorang tetamu dari buku teks!', 1),
(132, 702, 'e7_n2_s3', 'Petak pertama dijaga Beta. Perdana Menteri ialah Penasihat kepada Yang di-Pertuan Agong dan mengiringi Beta ke Mesyuarat Majlis Raja-Raja.', 2),
(126, 702, 'e7_n2_s3', 'Petak kedua aku jaga! Perdana Menteri mencadangkan senarai Jemaah Menteri dan mempengerusikan Mesyuarat Jemaah Menteri bagi menteri yang dilantik oleh Yang di-Pertuan Agong.', 3),
(127, 702, 'e7_n2_s3', 'Petak ketiga: Ketua Pentadbir Utama! Perdana Menteri merancang dan menyelaraskan semua dasar negara, serta memastikan pembangunan ditingkatkan demi kesejahteraan rakyat.', 4),
(125, 702, 'e7_n2_s3', 'Petak keempat milik aku: hubungan diplomatik. Perdana Menteri mencadangkan pelantikan duta, diplomat dan konsulat untuk menjalin kerjasama dengan negara luar.', 5),
(NULL, 702, 'e7_n2_s3', 'Empat petak, empat tugas! Murid-murid, bantu cikgu jawab soalan daripada tetamu kita ini.', 6),
(126, 702, 'e7_n2_s3', 'Cikgu! Mesyuarat Jemaah Menteri, siapakah yang mempengerusikannya?', 7),
(NULL, 702, 'e7_n2_s4', 'Eh, halaman buku teks bertukar jadi jalan lengang. Murid-murid, jangan takut, ini ingatan sejarah!', 1),
(124, 702, 'e7_n2_s4', 'Cikgu, aku Tunku. Aku memperjuangkan kemerdekaan secara rundingan, dan pada 16 September 1963 aku merealisasikan Pembentukan Malaysia.', 2),
(125, 702, 'e7_n2_s4', 'Tun Abdul Razak di sini. Jalan ini sunyi selepas peristiwa 13 Mei 1969. Aku mengembalikan keamanan menerusi Majlis Gerakan Negara (MAGERAN).', 3),
(125, 702, 'e7_n2_s4', 'Aku juga memperkenalkan Dasar Ekonomi Baru (DEB) untuk membasmi kemiskinan dan menyusun semula masyarakat.', 4),
(126, 702, 'e7_n2_s4', 'Aku Tun Hussein Onn. Aku memperkenalkan Amanah Saham Nasional Berhad (ASNB) untuk pemilikan saham bumiputera.', 5),
(126, 702, 'e7_n2_s4', 'Dan Program Rukun Tetangga untuk perpaduan. Jiran bertegur sapa, negara aman, cikgu!', 6),
(NULL, 702, 'e7_n2_s4', 'Empat peristiwa ini bercampur-baur. Cikgu mahu susun mengikut urutan, tapi murid-murid keliru!', 7),
(125, 702, 'e7_n2_s4', 'Sebelum cikgu susun, jawab dahulu. MAGERAN itu kepanjangan apa?', 8),
(127, 702, 'e7_n2_s5', 'Cikgu! Buku teks ini jadi bandar. Aku Tun Dr. Mahathir, dan inilah Wawasan 2020 aku!', 1),
(127, 702, 'e7_n2_s5', 'Pembinaan Putrajaya, KLIA dan Menara Berkembar Petronas (KLCC) berlaku pada zamanku, cikgu!', 2),
(127, 702, 'e7_n2_s5', 'Kilang itu pula berkait dengan HICOM, yang aku tubuhkan untuk industri berteknologi tinggi.', 3),
(128, 702, 'e7_n2_s5', 'Aku Tun Abdullah Ahmad Badawi, cikgu. Pencapaianku ialah Koridor Wilayah Ekonomi dan Pelan Integriti Nasional (PIN).', 4),
(128, 702, 'e7_n2_s5', 'Koridor itu ekonomi, PIN itu integriti. Dua perkara berbeza, jangan tertukar, ya!', 5),
(NULL, 702, 'e7_n2_s5', 'Murid-murid, mari cari bukti pencapaian Tun Dr. Mahathir pada gambar bandar ini. Tunjukkan dengan jari!', 6),
(127, 702, 'e7_n2_s5', 'Sebelum itu, soalan aku: HICOM ditubuhkan untuk industri jenis apa?', 7),
(NULL, 702, 'e7_n2_s6', 'Murid-murid, bab terakhir! Tiga Perdana Menteri terakhir dalam senarai. Siapa mahu mula?', 1),
(129, 702, 'e7_n2_s6', 'Aku Dato'' Sri Najib, cikgu. Aku memperkenalkan Gagasan 1Malaysia dan Program Transformasi Kerajaan (GTP).', 2),
(130, 702, 'e7_n2_s6', 'Tan Sri Muhyiddin di sini. Aku menubuhkan Majlis Tindakan Ekonomi (MTE) dan mengumumkan bantuan kewangan serta peruntukan besar semasa PKP pandemik COVID-19.', 3),
(131, 702, 'e7_n2_s6', 'Aku Dato'' Seri Ismail Sabri. Aku memperkenalkan Keluarga Malaysia, konsep yang meraikan keterangkuman pelbagai agama, bangsa, kaum dan usia.', 4),
(NULL, 702, 'e7_n2_s6', 'Terima kasih, tuan-tuan! Murid-murid, catat: 1Malaysia dan GTP, MTE dan bantuan PKP, Keluarga Malaysia. Eh, kertas tugasan cikgu luntur sedikit!', 5),
(129, 702, 'e7_n2_s6', 'Cikgu, aku tanya dahulu sebelum cikgu baca: GTP itu apa?', 6),
(123, 703, NULL, 'Tugasku ialah mengumpul semua kad supaya kawan-kawan mengenali pemimpin negara. Jika murid berhenti menyelidik, album pun tinggal kosong, {nama}. Terima kasih kerana meminjamkan tanganmu!', 1),
(123, 703, NULL, 'Setiap kad dalam album itu ialah satu cerita tentang pemimpin negara. Apabila kita menyusunnya dengan betul, sejarah menjadi mudah diingat.', 2),
(123, 703, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, murid yang bersemangat dengan album kad kosong dan pensel di telinga. Projek besar bermula sekarang! Lihat dengan matanya dan bercakaplah dengan suaranya.', 3),
(NULL, 703, 'e7_n3_s1', 'Projekku: album kad koleksi Perdana Menteri! Tapi kad pertama masih kosong. Ayuh cari maklumat di Wilayah Persekutuan!', 1),
(132, 703, 'e7_n3_s1', 'Wahai murid penyelidik, Beta Yang di-Pertuan Agong. Beta ialah Ketua Utama Negara, dan Beta melantik Perdana Menteri secara rasmi.', 2),
(124, 703, 'e7_n3_s1', 'Aku Tunku. Perdana Menteri ialah Ketua Kerajaan yang mengetuai pentadbiran negara. Tulis di kad pertama, murid!', 3),
(124, 703, 'e7_n3_s1', 'Jawatan ini diwujudkan selepas kemerdekaan. Dan lihat, ia kekal hingga kini. Kad ini takkan lapuk!', 4),
(132, 703, 'e7_n3_s1', 'Ingat pesan Beta: Ketua Utama Negara melantik, Ketua Kerajaan mentadbir. Dua jawatan, dua peranan.', 5),
(NULL, 703, 'e7_n3_s1', 'Tulis! Ketua Kerajaan, dilantik oleh Yang di-Pertuan Agong, diwujudkan selepas kemerdekaan, kekal hingga kini. Wah, kad pertama penuh!', 6),
(124, 703, 'e7_n3_s1', 'Murid, soalan pantas Tunku: jawatan Perdana Menteri diwujudkan bila?', 7),
(NULL, 703, 'e7_n3_s2', 'Kad kedua hingga kesembilan dalam album masih bercampur. Aku mesti letak ikut giliran Perdana Menteri. Tolong, tuan-tuan!', 1),
(124, 703, 'e7_n3_s2', 'Kad pertama sudah milik aku, Tunku Abdul Rahman Putra Al-Haj, Perdana Menteri pertama.', 2),
(125, 703, 'e7_n3_s2', 'Kad kedua: Tun Abdul Razak bin Hussein. Kemudian kad ketiga milik Tun Hussein bin Onn.', 3),
(126, 703, 'e7_n3_s2', 'Betul! Aku ketiga. Kemudian Tun Dr. Mahathir bin Mohamad pula, yang keempat.', 4),
(127, 703, 'e7_n3_s2', 'Aku muncul dua kali dalam album: keempat dan ketujuh. Jangan lupa tampal dua kad untukku!', 5),
(128, 703, 'e7_n3_s2', 'Kad kelima: Tun Abdullah bin Ahmad Badawi, murid. Selepas Tun Dr. Mahathir yang keempat.', 6),
(129, 703, 'e7_n3_s2', 'Kad keenam: Dato'' Sri Mohd Najib bin Tun Abdul Razak. Letak elok-elok, ya!', 7),
(130, 703, 'e7_n3_s2', 'Selepas kad ketujuh Tun Dr. Mahathir, kad kelapan ialah aku, Tan Sri Muhyiddin bin Md Yassin.', 8),
(131, 703, 'e7_n3_s2', 'Dan kad kesembilan, penutup album: Dato'' Seri Ismail Sabri bin Yaakob. Selesai!', 9),
(127, 703, 'e7_n3_s2', 'Murid, sebelum album ditutup, soalan aku: dalam album ini, aku diletakkan pada giliran yang mana?', 10),
(NULL, 703, 'e7_n3_s3', 'Kad tugas Perdana Menteri ada empat. Ayuh, tuan-tuan, isi kad ini bersama-sama! Pensel sedia!', 1),
(132, 703, 'e7_n3_s3', 'Kad pertama daripada Beta: Perdana Menteri ialah Penasihat kepada Yang di-Pertuan Agong, dan mengiringi Beta ke Mesyuarat Majlis Raja-Raja.', 2),
(125, 703, 'e7_n3_s3', 'Kad kedua: mencadangkan senarai Jemaah Menteri. Perdana Menteri juga mempengerusikan Mesyuarat Jemaah Menteri bagi menteri yang dilantik oleh Yang di-Pertuan Agong.', 3),
(128, 703, 'e7_n3_s3', 'Kad ketiga: Ketua Pentadbir Utama. Merancang dan menyelaraskan semua dasar negara serta memastikan pembangunan ditingkatkan demi kesejahteraan rakyat.', 4),
(131, 703, 'e7_n3_s3', 'Kad keempat: hubungan diplomatik. Mencadangkan pelantikan duta, diplomat dan konsulat untuk menjalin kerjasama dengan negara luar.', 5),
(NULL, 703, 'e7_n3_s3', 'Penuh! Tapi kad keempat luntur terkena air minuman. Tolong nyahkodkan!', 6),
(131, 703, 'e7_n3_s3', 'Sebelum itu, soalan aku: duta dan konsulat menjalin kerjasama dengan siapa?', 7),
(NULL, 703, 'e7_n3_s4', 'Peta besar Pembentukan Malaysia terbentang di meja. Albumku kini ke halaman Tunku, Tun Abdul Razak dan Tun Hussein Onn!', 1),
(124, 703, 'e7_n3_s4', 'Murid, aku memperjuangkan kemerdekaan secara rundingan. Pada 16 September 1963, aku merealisasikan Pembentukan Malaysia.', 2),
(125, 703, 'e7_n3_s4', 'Selepas peristiwa 13 Mei 1969, aku mengembalikan keamanan menerusi MAGERAN. Aku juga memperkenalkan Dasar Ekonomi Baru (DEB).', 3),
(125, 703, 'e7_n3_s4', 'DEB bertujuan membasmi kemiskinan dan menyusun semula masyarakat. Ingat, murid: kemiskinan dibasmi, masyarakat disusun!', 4),
(126, 703, 'e7_n3_s4', 'Aku Tun Hussein Onn. Aku memperkenalkan ASNB supaya bumiputera memiliki saham, dan Program Rukun Tetangga untuk perpaduan.', 5),
(NULL, 703, 'e7_n3_s4', 'Hebat! Kad-kadku makin bernilai. Tapi aku mahu padankan semuanya dahulu.', 6),
(124, 703, 'e7_n3_s4', 'Murid, soalan Tunku: kemerdekaan diperjuangkan secara apa?', 7),
(NULL, 703, 'e7_n3_s5', 'Kad Tun Dr. Mahathir dan Tun Abdullah paling tebal. Aku di hadapan bangunan pentadbiran negara. Siapa tolong ceritakan?', 1),
(127, 703, 'e7_n3_s5', 'Murid penyelidik, aku Tun Dr. Mahathir. Kad aku penuh: Wawasan 2020, pembinaan Putrajaya, KLIA dan Menara Berkembar Petronas (KLCC).', 2),
(127, 703, 'e7_n3_s5', 'Dan kad HICOM juga, penubuhan untuk industri berteknologi tinggi. Susun betul-betul, nanti kad jatuh!', 3),
(128, 703, 'e7_n3_s5', 'Kad aku, Tun Abdullah Ahmad Badawi: Koridor Wilayah Ekonomi dan Pelan Integriti Nasional (PIN).', 4),
(NULL, 703, 'e7_n3_s5', 'Dua kad penuh! Nota lengkap: Wawasan 2020, Putrajaya, KLIA, KLCC, HICOM, Koridor Wilayah Ekonomi, PIN. Siap!', 5),
(128, 703, 'e7_n3_s5', 'Soalan aku, murid: PIN itu kepanjangan apa?', 6),
(NULL, 703, 'e7_n3_s6', 'Kad terakhir album! Tiga kad: Perdana Menteri keenam, kelapan dan kesembilan. Siapa mula?', 1),
(129, 703, 'e7_n3_s6', 'Murid, aku Dato'' Sri Najib. Kad aku: Gagasan 1Malaysia dan Program Transformasi Kerajaan (GTP). Aku Perdana Menteri keenam.', 2),
(130, 703, 'e7_n3_s6', 'Aku Tan Sri Muhyiddin, Perdana Menteri kelapan. Kadku: Majlis Tindakan Ekonomi (MTE), serta bantuan kewangan dan peruntukan besar semasa PKP pandemik COVID-19.', 3),
(131, 703, 'e7_n3_s6', 'Aku Dato'' Seri Ismail Sabri, kesembilan. Kad aku: Keluarga Malaysia, yang meraikan keterangkuman pelbagai agama, bangsa, kaum dan usia.', 4),
(NULL, 703, 'e7_n3_s6', 'Album siap! Tapi tiga kad ini mesti disusun ikut giliran Perdana Menteri.', 5),
(131, 703, 'e7_n3_s6', 'Murid, soalan penutup aku: konsep Keluarga Malaysia diperkenalkan oleh siapa?', 6);
INSERT INTO QuestionBank (bankID, eraID) VALUES (7, 7)
INSERT INTO Question (questionID, bankID, questionText, option_a, option_b, option_c, option_d, correctAnswer, hint, explanation) VALUES
(701, 7, 'Siapakah Ketua Kerajaan yang mengetuai pentadbiran negara Malaysia?', 'Yang di-Pertuan Agong', 'Perdana Menteri', 'Ketua Hakim Negara', 'Speaker Dewan Rakyat', 'B', 'Ketua Kerajaan berbeza daripada Ketua Utama Negara.', 'Perdana Menteri ialah Ketua Kerajaan yang mengetuai pentadbiran negara.'),
(702, 7, 'Siapakah yang melantik Perdana Menteri secara rasmi?', 'Ketua Hakim Negara', 'Speaker Dewan Rakyat', 'Yang di-Pertuan Agong', 'Setiausaha Kerajaan Negeri', 'C', 'Beliau juga ialah Ketua Utama Negara.', 'Perdana Menteri dilantik secara rasmi oleh Yang di-Pertuan Agong, Ketua Utama Negara.'),
(703, 7, 'Yang di-Pertuan Agong dikenali sebagai apa dalam negara?', 'Ketua Kerajaan negara', 'Ketua Pentadbir Utama', 'Ketua Pembangkang rasmi', 'Ketua Utama Negara', 'D', 'Perdana Menteri pula ialah Ketua Kerajaan.', 'Yang di-Pertuan Agong ialah Ketua Utama Negara, manakala Perdana Menteri ialah Ketua Kerajaan.'),
(704, 7, 'Bilakah jawatan Perdana Menteri diwujudkan?', 'Selepas kemerdekaan', 'Sebelum kemerdekaan dicapai', 'Selepas peristiwa 13 Mei 1969', 'Selepas Wawasan 2020 dilancarkan', 'A', 'Tunku Abdul Rahman ialah Perdana Menteri pertama.', 'Jawatan Perdana Menteri diwujudkan selepas kemerdekaan.'),
(705, 7, 'Sehingga bilakah jawatan Perdana Menteri kekal dalam negara kita?', 'Dimansuhkan selepas Pembentukan Malaysia', 'Sehingga hari ini', 'Dimansuhkan selepas peristiwa 13 Mei 1969', 'Hanya sehingga Perdana Menteri keempat', 'B', 'Senarai Perdana Menteri sudah mencecah sembilan giliran.', 'Jawatan ini diwujudkan selepas kemerdekaan dan kekal hingga kini.'),
(706, 7, 'Yang manakah pernyataan yang betul tentang jawatan Perdana Menteri?', 'Ketua Kerajaan yang mengetuai pentadbiran negara dan dilantik secara rasmi oleh Yang di-Pertuan Agong', 'Ketua Utama Negara yang mengetuai pentadbiran negara dan dilantik secara rasmi oleh Dewan Rakyat', 'Ketua Kerajaan yang diwujudkan sebelum kemerdekaan dan dimansuhkan selepas itu oleh Parlimen', 'Ketua Utama Negara yang dilantik secara rasmi oleh Perdana Menteri yang terdahulu', 'A', 'Ingat dua ketua dan dua tugas yang berbeza.', 'Perdana Menteri ialah Ketua Kerajaan dan dilantik secara rasmi oleh Yang di-Pertuan Agong.'),
(707, 7, 'Siapakah Perdana Menteri pertama Malaysia?', 'Tun Abdul Razak bin Hussein', 'Tun Hussein bin Onn', 'Tun Dr. Mahathir bin Mohamad', 'Tunku Abdul Rahman Putra Al-Haj', 'D', 'Beliau memperjuangkan kemerdekaan secara rundingan.', 'Tunku Abdul Rahman Putra Al-Haj ialah Perdana Menteri pertama.'),
(708, 7, 'Siapakah Perdana Menteri kedua Malaysia?', 'Tun Abdul Razak bin Hussein', 'Tunku Abdul Rahman Putra Al-Haj', 'Tun Hussein bin Onn', 'Tun Abdullah bin Ahmad Badawi', 'A', 'Beliau memperkenalkan Dasar Ekonomi Baru.', 'Tun Abdul Razak bin Hussein ialah Perdana Menteri kedua.'),
(709, 7, 'Siapakah Perdana Menteri ketiga Malaysia?', 'Tun Abdul Razak bin Hussein', 'Tun Hussein bin Onn', 'Tun Dr. Mahathir bin Mohamad', 'Tun Abdullah bin Ahmad Badawi', 'B', 'Beliau memperkenalkan ASNB dan Rukun Tetangga.', 'Tun Hussein bin Onn ialah Perdana Menteri ketiga.'),
(710, 7, 'Siapakah Perdana Menteri keempat Malaysia?', 'Tun Hussein bin Onn', 'Tun Dr. Mahathir bin Mohamad', 'Tun Abdullah bin Ahmad Badawi', 'Dato'' Sri Mohd Najib bin Tun Abdul Razak', 'B', 'Beliau menjadi Perdana Menteri sekali lagi pada giliran ketujuh.', 'Tun Dr. Mahathir bin Mohamad ialah Perdana Menteri keempat dan juga ketujuh.'),
(711, 7, 'Siapakah Perdana Menteri kelima Malaysia?', 'Dato'' Sri Mohd Najib bin Tun Abdul Razak', 'Tan Sri Muhyiddin bin Md Yassin', 'Dato'' Seri Ismail Sabri bin Yaakob', 'Tun Abdullah bin Ahmad Badawi', 'D', 'Beliau datang selepas Perdana Menteri keempat.', 'Tun Abdullah bin Ahmad Badawi ialah Perdana Menteri kelima.'),
(712, 7, 'Siapakah Perdana Menteri keenam Malaysia?', 'Tun Abdullah bin Ahmad Badawi', 'Dato'' Sri Mohd Najib bin Tun Abdul Razak', 'Dato'' Seri Ismail Sabri bin Yaakob', 'Tan Sri Muhyiddin bin Md Yassin', 'B', 'Beliau memperkenalkan Gagasan 1Malaysia.', 'Dato'' Sri Mohd Najib bin Tun Abdul Razak ialah Perdana Menteri keenam.'),
(713, 7, 'Siapakah yang menjadi Perdana Menteri pada giliran keempat dan juga ketujuh?', 'Tun Abdullah bin Ahmad Badawi', 'Tun Dr. Mahathir bin Mohamad', 'Dato'' Sri Mohd Najib bin Tun Abdul Razak', 'Tan Sri Muhyiddin bin Md Yassin', 'B', 'Seorang tokoh muncul dua kali dalam senarai.', 'Tun Dr. Mahathir bin Mohamad ialah Perdana Menteri keempat dan ketujuh.'),
(714, 7, 'Siapakah Perdana Menteri kelapan dan kesembilan, mengikut giliran?', 'Tan Sri Muhyiddin bin Md Yassin, kemudian Dato'' Seri Ismail Sabri bin Yaakob', 'Dato'' Seri Ismail Sabri bin Yaakob, kemudian Tan Sri Muhyiddin bin Md Yassin', 'Dato'' Sri Mohd Najib bin Tun Abdul Razak, kemudian Tan Sri Muhyiddin bin Md Yassin', 'Tun Dr. Mahathir bin Mohamad, kemudian Dato'' Seri Ismail Sabri bin Yaakob', 'A', 'Kelapan dahulu, baru kesembilan.', 'Perdana Menteri kelapan ialah Tan Sri Muhyiddin bin Md Yassin dan kesembilan ialah Dato'' Seri Ismail Sabri bin Yaakob.'),
(715, 7, 'Sebagai penasihat kepada Yang di-Pertuan Agong, apakah yang dilakukan oleh Perdana Menteri?', 'Mempengerusikan Mesyuarat Majlis Raja-Raja menggantikan baginda sendiri', 'Mengiringi Yang di-Pertuan Agong ke Mesyuarat Majlis Raja-Raja', 'Memilih Raja-Raja yang akan hadir ke Mesyuarat Majlis Raja-Raja itu', 'Menyampaikan titah Yang di-Pertuan Agong tanpa mengiringi baginda ke mesyuarat', 'B', 'Perdana Menteri mengiringi, bukan mempengerusikan.', 'Perdana Menteri menjadi penasihat dan mengiringi Yang di-Pertuan Agong ke Mesyuarat Majlis Raja-Raja.'),
(716, 7, 'Mesyuarat manakah yang diiringi oleh Perdana Menteri bersama Yang di-Pertuan Agong?', 'Mesyuarat Majlis Raja-Raja', 'Mesyuarat Majlis Tindakan Ekonomi', 'Mesyuarat Dewan Undangan Negeri', 'Mesyuarat Agung Pertubuhan Pelajar', 'A', 'Majlis ini dihadiri oleh Raja-Raja.', 'Perdana Menteri mengiringi Yang di-Pertuan Agong ke Mesyuarat Majlis Raja-Raja.'),
(717, 7, 'Siapakah yang mempengerusikan Mesyuarat Jemaah Menteri?', 'Perdana Menteri', 'Yang di-Pertuan Agong', 'Ketua Setiausaha Negara', 'Speaker Dewan Rakyat', 'A', 'Beliau juga mencadangkan senarai Jemaah Menteri.', 'Perdana Menteri mempengerusikan Mesyuarat Jemaah Menteri.'),
(718, 7, 'Siapakah yang mencadangkan senarai Jemaah Menteri?', 'Majlis Raja-Raja negeri', 'Ketua Setiausaha Negara', 'Perdana Menteri', 'Speaker Dewan Rakyat', 'C', 'Menteri itu kemudian dilantik oleh Yang di-Pertuan Agong.', 'Perdana Menteri mencadangkan senarai Jemaah Menteri bagi menteri yang dilantik oleh Yang di-Pertuan Agong.'),
(719, 7, 'Apakah yang dilakukan oleh Perdana Menteri sebagai Ketua Pentadbir Utama?', 'Mengubah semua undang-undang negeri tanpa persetujuan sesiapa pun', 'Menyelaraskan dasar bagi satu negeri tertentu sahaja setiap tahun', 'Menjaga istana dan mengurus majlis rasmi kerajaan negeri sahaja', 'Merancang dan menyelaraskan semua dasar negara demi kesejahteraan rakyat', 'D', 'Dasar negara itu untuk semua rakyat.', 'Perdana Menteri merancang dan menyelaraskan semua dasar negara serta memastikan pembangunan ditingkatkan demi kesejahteraan rakyat.'),
(720, 7, 'Apakah tujuan Perdana Menteri memastikan pembangunan ditingkatkan?', 'Demi kepentingan negara jiran semata-mata', 'Demi kemasyhuran Perdana Menteri sendiri', 'Demi mengurangkan bilangan menteri', 'Demi kesejahteraan rakyat', 'D', 'Ia berkait dengan kehidupan rakyat.', 'Pembangunan ditingkatkan demi kesejahteraan rakyat.'),
(721, 7, 'Apakah tugas Perdana Menteri dalam menjalin hubungan diplomatik?', 'Mencadangkan pelantikan duta, diplomat dan konsulat', 'Melantik sendiri duta tanpa sebarang cadangan kerajaan', 'Menjadi duta kepada semua negara serentak', 'Menghantar surat kepada Majlis Raja-Raja sahaja', 'A', 'Tiga jawatan yang dicadangkan untuk negara luar.', 'Perdana Menteri mencadangkan pelantikan duta, diplomat dan konsulat untuk menjalin kerjasama dengan negara luar.'),
(722, 7, 'Antara yang berikut, yang manakah BUKAN tugas Perdana Menteri?', 'Mempengerusikan Mesyuarat Jemaah Menteri', 'Mencadangkan pelantikan duta, diplomat dan konsulat', 'Mengiringi Yang di-Pertuan Agong ke Mesyuarat Majlis Raja-Raja', 'Melantik sendiri Yang di-Pertuan Agong', 'D', 'Ingat siapa yang melantik Perdana Menteri.', 'Perdana Menteri dilantik oleh Yang di-Pertuan Agong, bukan sebaliknya.'),
(723, 7, 'Bagaimanakah Tunku Abdul Rahman memperjuangkan kemerdekaan?', 'Secara peperangan terbuka', 'Secara rundingan', 'Secara pemberontakan bersenjata', 'Secara pengusiran serta-merta', 'B', 'Beliau memilih berunding, bukan berperang.', 'Tunku memperjuangkan kemerdekaan secara rundingan.'),
(724, 7, 'Pada tarikh manakah Pembentukan Malaysia direalisasikan?', 'Pada 13 Mei 1969 itu juga', 'Pada 16 September 1963', 'Pada 31 Ogos 1957 dahulu', 'Pada 31 Disember 1999 itu', 'B', 'Ia berlaku pada zaman Perdana Menteri pertama.', 'Tunku merealisasikan Pembentukan Malaysia pada 16 September 1963.'),
(725, 7, 'Apakah pencapaian utama Tunku Abdul Rahman Putra Al-Haj?', 'Dasar Ekonomi Baru dan Majlis Gerakan Negara', 'Pembinaan Putrajaya dan Menara Berkembar Petronas', 'Kemerdekaan secara rundingan dan Pembentukan Malaysia', 'Amanah Saham Nasional Berhad dan Rukun Tetangga', 'C', 'Satu pencapaian ialah pada 16 September 1963.', 'Tunku memperjuangkan kemerdekaan secara rundingan dan merealisasikan Pembentukan Malaysia.'),
(726, 7, 'Peristiwa manakah yang mendahului penubuhan MAGERAN?', 'Pembentukan Malaysia 1963', 'Perintah Kawalan Pergerakan', 'Peristiwa 13 Mei 1969', 'Pengisytiharan Wawasan 2020', 'C', 'Tun Abdul Razak mengembalikan keamanan selepas peristiwa itu.', 'Tun Abdul Razak mengembalikan keamanan selepas peristiwa 13 Mei 1969 menerusi MAGERAN.'),
(727, 7, 'MAGERAN ialah singkatan bagi apakah?', 'Majlis Gabungan Negara', 'Majlis Gerakan Nasional', 'Majlis Gotong-royong Negeri', 'Majlis Gerakan Negara', 'D', 'Majlis ini mengembalikan keamanan.', 'MAGERAN bermaksud Majlis Gerakan Negara.'),
(728, 7, 'Apakah tujuan Dasar Ekonomi Baru (DEB)?', 'Membina kota pentadbiran baharu di Putrajaya', 'Menggalakkan industri berteknologi tinggi sahaja', 'Membasmi kemiskinan dan menyusun semula masyarakat', 'Memberi bantuan kewangan semasa pandemik', 'C', 'Dua tujuan: kemiskinan dan masyarakat.', 'DEB diperkenalkan untuk membasmi kemiskinan dan menyusun semula masyarakat.'),
(729, 7, 'Apakah pencapaian Tun Abdul Razak Hussein?', 'Memperkenalkan Wawasan 2020 dan membina Putrajaya serta KLIA', 'Memperkenalkan ASNB dan Program Rukun Tetangga untuk perpaduan', 'Memperkenalkan Gagasan 1Malaysia dan Program Transformasi Kerajaan', 'Mengembalikan keamanan melalui MAGERAN dan memperkenalkan DEB', 'D', 'Selepas 13 Mei 1969.', 'Tun Abdul Razak mengembalikan keamanan melalui MAGERAN dan memperkenalkan Dasar Ekonomi Baru.'),
(730, 7, 'Apakah tujuan Amanah Saham Nasional Berhad (ASNB)?', 'Pembinaan lebuh raya baharu', 'Pemilikan saham bumiputera', 'Bantuan kewangan semasa PKP', 'Pelan integriti penjawat awam', 'B', 'Ia berkait dengan saham.', 'ASNB diperkenalkan oleh Tun Hussein Onn untuk pemilikan saham bumiputera.'),
(731, 7, 'Apakah tujuan Program Rukun Tetangga?', 'Pemilikan saham bumiputera', 'Pembinaan koridor ekonomi', 'Bantuan kewangan semasa pandemik', 'Perpaduan', 'D', 'Jiran saling bertegur sapa.', 'Program Rukun Tetangga diperkenalkan oleh Tun Hussein Onn untuk perpaduan.'),
(732, 7, 'Siapakah yang memperkenalkan ASNB dan Program Rukun Tetangga?', 'Tun Abdul Razak Hussein', 'Tun Dr. Mahathir Mohamad', 'Tun Hussein Onn', 'Tun Abdullah Ahmad Badawi', 'C', 'Perdana Menteri ketiga.', 'Tun Hussein Onn memperkenalkan ASNB dan Program Rukun Tetangga.'),
(733, 7, 'Siapakah yang memperkenalkan Wawasan 2020?', 'Tun Abdul Razak Hussein', 'Tun Abdullah Ahmad Badawi', 'Tun Dr. Mahathir Mohamad', 'Dato'' Sri Mohd Najib Tun Abdul Razak', 'C', 'Perdana Menteri keempat dan ketujuh.', 'Wawasan 2020 diperkenalkan oleh Tun Dr. Mahathir Mohamad.'),
(734, 7, 'Apakah tujuan penubuhan HICOM?', 'Untuk bantuan kewangan semasa PKP', 'Untuk pemilikan saham bumiputera sahaja', 'Untuk menyusun semula masyarakat', 'Untuk industri berteknologi tinggi', 'D', 'Kilang dan mesin moden.', 'HICOM ditubuhkan oleh Tun Dr. Mahathir untuk industri berteknologi tinggi.'),
(735, 7, 'Apakah nama lain bagi Menara Berkembar Petronas?', 'KLIA', 'HICOM', 'PIN', 'KLCC', 'D', 'Singkatan nama pusat bandar tersebut.', 'Menara Berkembar Petronas turut dikenali sebagai KLCC.'),
(736, 7, 'Binaan manakah yang dikaitkan dengan kepimpinan Tun Dr. Mahathir?', 'Putrajaya, KLIA dan Menara Berkembar Petronas (KLCC)', 'Putrajaya, ASNB dan Menara Berkembar Petronas (KLCC)', 'KLIA, MAGERAN dan Menara Berkembar Petronas (KLCC)', 'Putrajaya, KLIA dan Koridor Wilayah Ekonomi (KLCC)', 'A', 'Tiga binaan besar pada zaman Perdana Menteri keempat.', 'Pembinaan Putrajaya, KLIA dan Menara Berkembar Petronas (KLCC) dikaitkan dengan Tun Dr. Mahathir.'),
(737, 7, 'Yang manakah pencapaian Tun Dr. Mahathir Mohamad?', 'Wawasan 2020, Koridor Wilayah Ekonomi dan PIN', 'Gagasan 1Malaysia, GTP, KLIA dan HICOM', 'Wawasan 2020, Putrajaya, KLIA, KLCC dan HICOM', 'Wawasan 2020, MTE, KLCC dan Keluarga Malaysia', 'C', 'Banyak pembinaan besar dan satu wawasan.', 'Pencapaian Tun Dr. Mahathir ialah Wawasan 2020, Putrajaya, KLIA, KLCC dan HICOM.'),
(738, 7, 'Apakah pencapaian Tun Abdullah Ahmad Badawi?', 'Gagasan 1Malaysia dan Program Transformasi Kerajaan (GTP)', 'Koridor Wilayah Ekonomi dan Pelan Integriti Nasional (PIN)', 'Majlis Tindakan Ekonomi (MTE) dan bantuan semasa PKP', 'Wawasan 2020 dan pembinaan Putrajaya dan KLIA', 'B', 'Perdana Menteri kelima.', 'Tun Abdullah Ahmad Badawi memperkenalkan Koridor Wilayah Ekonomi dan Pelan Integriti Nasional (PIN).'),
(739, 7, 'PIN ialah singkatan bagi apakah?', 'Pelan Integriti Nasional', 'Pelan Industri Nasional', 'Program Integriti Negara', 'Pelan Insentif Negeri', 'A', 'Ia berkait dengan integriti.', 'PIN bermaksud Pelan Integriti Nasional.'),
(740, 7, 'Siapakah yang memperkenalkan Gagasan 1Malaysia?', 'Tun Abdullah Ahmad Badawi', 'Tan Sri Muhyiddin Md Yassin', 'Dato'' Sri Mohd Najib Tun Abdul Razak', 'Dato'' Seri Ismail Sabri Yaakob', 'C', 'Perdana Menteri keenam.', 'Gagasan 1Malaysia dan GTP diperkenalkan oleh Dato'' Sri Mohd Najib Tun Abdul Razak.'),
(741, 7, 'GTP ialah singkatan bagi apakah?', 'Program Transformasi Kerajaan', 'Program Tindakan Ekonomi Rakyat', 'Pelan Transformasi Industri Negeri', 'Gagasan Tindakan Perpaduan Rakyat', 'A', 'Program ini diperkenalkan bersama Gagasan 1Malaysia.', 'GTP bermaksud Program Transformasi Kerajaan (Government Transformation Programme).'),
(742, 7, 'Majlis manakah yang ditubuhkan oleh Tan Sri Muhyiddin Md Yassin?', 'Majlis Gerakan Negara (MAGERAN)', 'Majlis Tindakan Ekonomi (MTE)', 'Majlis Raja-Raja', 'Majlis Integriti Nasional', 'B', 'Majlis ini berkait dengan ekonomi.', 'Tan Sri Muhyiddin Md Yassin menubuhkan Majlis Tindakan Ekonomi (MTE).'),
(743, 7, 'Semasa apakah bantuan kewangan dan peruntukan besar diumumkan oleh Tan Sri Muhyiddin?', 'Semasa PKP pandemik COVID-19', 'Semasa peristiwa 13 Mei 1969', 'Semasa Pembentukan Malaysia', 'Semasa pelancaran Wawasan 2020', 'A', 'PKP bermaksud Perintah Kawalan Pergerakan.', 'Bantuan kewangan dan peruntukan besar diumumkan semasa Perintah Kawalan Pergerakan (PKP) pandemik COVID-19.'),
(744, 7, 'Apakah pencapaian Tan Sri Muhyiddin Md Yassin?', 'Menubuhkan MTE dan mengumumkan bantuan semasa PKP', 'Memperkenalkan Keluarga Malaysia dan Wawasan 2020', 'Memperkenalkan Gagasan 1Malaysia dan GTP', 'Memperkenalkan PIN dan Koridor Wilayah Ekonomi', 'A', 'Perdana Menteri kelapan.', 'Tan Sri Muhyiddin menubuhkan MTE dan mengumumkan bantuan kewangan serta peruntukan besar semasa PKP.'),
(745, 7, 'Apakah konsep yang diperkenalkan oleh Dato'' Seri Ismail Sabri Yaakob?', 'Gagasan 1Malaysia', 'Wawasan 2020', 'Keluarga Malaysia', 'Rukun Tetangga', 'C', 'Perdana Menteri kesembilan.', 'Dato'' Seri Ismail Sabri Yaakob memperkenalkan konsep Keluarga Malaysia.'),
(746, 7, 'Apakah yang diraikan oleh konsep Keluarga Malaysia?', 'Keterangkuman satu bangsa dan satu agama sahaja', 'Keterangkuman pelbagai negara jiran', 'Keterangkuman pelbagai agama, bangsa, kaum dan usia', 'Keterangkuman kumpulan peniaga dan pelabur', 'C', 'Semua orang ada tempat dalam keluarga.', 'Keluarga Malaysia meraikan keterangkuman pelbagai agama, bangsa, kaum dan usia.'),
(747, 7, 'Berapakah giliran Perdana Menteri dalam senarai, dan mengapa jumlah orangnya lebih sedikit?', 'Sembilan giliran, kerana Tun Dr. Mahathir menjadi Perdana Menteri dua kali', 'Sembilan giliran, kerana Tunku Abdul Rahman memegang jawatan dua kali', 'Lapan giliran, kerana Tun Dr. Mahathir memegang jawatan sekali', 'Sepuluh giliran, kerana ada dua orang memegang jawatan dua kali', 'A', 'Satu tokoh disebut pada giliran keempat dan ketujuh.', 'Senarai mempunyai sembilan giliran, tetapi Tun Dr. Mahathir ialah Perdana Menteri keempat dan ketujuh.'),
(748, 7, 'Yang manakah susunan pencapaian yang betul mengikut urutan Perdana Menteri?', 'MAGERAN dan DEB, kemudian ASNB dan Rukun Tetangga, kemudian kemerdekaan', 'ASNB dan Rukun Tetangga, kemudian kemerdekaan, kemudian MAGERAN dan DEB', 'Kemerdekaan secara rundingan, MAGERAN dan DEB, kemudian ASNB dan Rukun Tetangga', 'Kemerdekaan secara rundingan, ASNB dan Rukun Tetangga, kemudian MAGERAN dan DEB', 'C', 'Mulakan dengan Perdana Menteri pertama.', 'Tunku (kemerdekaan secara rundingan), Tun Abdul Razak (MAGERAN dan DEB) dan Tun Hussein Onn (ASNB dan Rukun Tetangga).'),
(749, 7, 'Yang manakah padanan Perdana Menteri dan pencapaiannya yang betul?', 'Tunku Abdul Rahman dan Amanah Saham Nasional', 'Tun Abdullah Badawi dan Wawasan 2020', 'Tun Abdul Razak dan Koridor Wilayah Ekonomi', 'Tun Hussein Onn dan Program Rukun Tetangga', 'D', 'Rukun Tetangga membawa perpaduan.', 'Program Rukun Tetangga diperkenalkan oleh Tun Hussein Onn.'),
(750, 7, 'Yang manakah padanan Perdana Menteri dan pencapaiannya yang betul?', 'Dato'' Sri Najib dan Majlis Tindakan Ekonomi', 'Dato'' Seri Ismail Sabri dan Keluarga Malaysia', 'Tan Sri Muhyiddin dan Gagasan 1Malaysia', 'Tun Dr. Mahathir dan Pelan Integriti Nasional', 'B', 'Konsep ini meraikan pelbagai agama, bangsa, kaum dan usia.', 'Dato'' Seri Ismail Sabri memperkenalkan konsep Keluarga Malaysia.');
